def fg(r,g,b):return f"\033[38;2;{int(r)};{int(g)};{int(b)}m"
def lerp(a,b,t):return tuple(a[i]+(b[i]-a[i])*t for i in range(3))
GOLD_FG=fg(*GOLD)
GREEN_FG=fg(*GREEN)
RED_FG=fg(220,80,80)
WHITE_FG=fg(221,221,221)
def gold(t):return f"{GOLD_FG}{t}{RESET}"
def green(t):return f"{GREEN_FG}{t}{RESET}"
def white(t):return f"{WHITE_FG}{t}{RESET}"
def dim(t):return f"{fg(*GOLD_DIM)}{t}{RESET}"
def strip_ansi(text):return re.sub(r"\033\[[^m]*m","",text)
def _normalize_repl_input(user):
    """Normalize ONE REPL line so a command can NEVER be mis-read as chat and hallucinated about (NX once told
    the operator '/message isn't a standard command' because the input arrived with a stray 'nx ' prefix and so
    didn't start with '/'). Strips surrounding whitespace, and drops a leading 'nx ' before a /command or $skill
    (a common paste habit: 'nx /message'). Menu sentinels ('__…') pass through untouched."""
    if not isinstance(user,str) or user.startswith("__"):return user
    u=user.strip()
    if u[:3].lower()=="nx " and u[3:].lstrip()[:1] in ("/","$"):
        u=u[3:].lstrip()
    return u
def _first_text(*values):
    for value in values:
        if isinstance(value,str):
            value=value.strip()
            if value:return value
    return None

def _clean_integration_description(description):
    description=(description or "").strip()
    description=description.split("—")[0].strip()
    description=description.split(" - ")[0].strip()
    description=description.split("(")[0].strip()
    return description

def _group_integrations_by_world(active_world,world_filter=None):
    by_world={}
    assigned=set()
    for name,mcp in MCP_REGISTRY.items():
        if name in assigned:
            continue
        mcp_worlds=mcp.get("worlds",[])
        if not mcp_worlds:
            continue
        primary_world=mcp_worlds[0]
        if world_filter and primary_world!=world_filter:
            continue
        by_world.setdefault(primary_world,[]).append((name,mcp))
        assigned.add(name)

    worlds=sorted(by_world.keys())
    if active_world in worlds:
        worlds.remove(active_world)
        worlds=[active_world]+worlds
    return worlds,by_world

def _resolve_world_name(world):
    return _first_text(world) or DEFAULT_WORLD

def _extract_stream_meta(obj):
    if not isinstance(obj,dict):return None,None
    metadata=obj.get("metadata") if isinstance(obj.get("metadata"),dict) else {}
    routing=obj.get("routing") if isinstance(obj.get("routing"),dict) else {}
    choices=obj.get("choices")
    choice=choices[0] if isinstance(choices,list) and choices and isinstance(choices[0],dict) else {}
    delta=choice.get("delta") if isinstance(choice.get("delta"),dict) else {}
    model=_first_text(
        obj.get("model"),
        obj.get("model_used"),
        metadata.get("model"),
        metadata.get("model_used"),
        routing.get("model"),
        choice.get("model"),
        delta.get("model"),
    )
    provider=_first_text(
        obj.get("provider"),
        metadata.get("provider"),
        routing.get("provider"),
        choice.get("provider"),
        delta.get("provider"),
    )
    return model,provider

