_GMAIL_MODIFY_ACTIONS = {"archive", "unarchive", "star", "unstar", "trash", "untrash", "delete",
                         "mark_read", "mark_unread", "spam", "not_spam", "apply_labels"}


def _gmail_action_dispatch(_ga):
    """Map a `gmail` tool call (action + params) to the /api/personal/gmail op and dispatch it. Returns
    (action, result). Fake-proof: delegates to nx_channel_tools._call_dispatch, which trusts only the route's
    {ok} envelope, so an un-deployed route is honest-pending, never a fabricated success."""
    _ga = _ga if isinstance(_ga, dict) else {}
    a = str(_ga.get("action") or "").strip().lower()
    mid = _ga.get("message_id") or _ga.get("id")
    if a in ("list", "search"):
        args = {"op": "list", "query": _ga.get("query"), "maxResults": _ga.get("max")}
    elif a in ("read", "get"):
        args = {"op": "get", "id": _ga.get("id") or _ga.get("message_id")}
    elif a == "thread":
        args = {"op": "thread", "id": _ga.get("id") or _ga.get("message_id")}
    elif a == "attachment":
        args = {"op": "attachment", "messageId": mid, "attachmentId": _ga.get("attachment_id")}
    elif a in ("drafts", "drafts_list"):
        args = {"op": "drafts_list", "maxResults": _ga.get("max")}
    elif a in ("labels", "labels_list"):
        args = {"op": "labels_list"}
    elif a in ("send", "compose"):
        args = {"op": "send", "to": _ga.get("to"), "subject": _ga.get("subject"), "body": _ga.get("body"),
                "html": _ga.get("html"), "cc": _ga.get("cc"), "bcc": _ga.get("bcc")}
    elif a == "reply":
        args = {"op": "reply", "messageId": mid, "body": _ga.get("body"), "html": _ga.get("html"), "to": _ga.get("to")}
    elif a == "draft":
        args = {"op": "draft", "action": "create", "to": _ga.get("to"), "subject": _ga.get("subject"),
                "body": _ga.get("body"), "html": _ga.get("html"), "cc": _ga.get("cc")}
    elif a == "send_draft":
        args = {"op": "draft", "action": "send", "draftId": _ga.get("draft_id")}
    elif a == "delete_draft":
        args = {"op": "draft", "action": "delete", "draftId": _ga.get("draft_id")}
    elif a in _GMAIL_MODIFY_ACTIONS:
        args = {"op": "modify", "messageId": mid, "action": a,
                "addLabelIds": _ga.get("add_label_ids"), "removeLabelIds": _ga.get("remove_label_ids")}
    elif a == "filter_list":
        args = {"op": "filter", "action": "list"}
    elif a == "filter_create":
        args = {"op": "filter", "action": "create", "criteria": _ga.get("criteria"),
                "filterAction": _ga.get("filter_action")}
    elif a == "filter_delete":
        args = {"op": "filter", "action": "delete", "filterId": _ga.get("filter_id")}
    else:
        return (a or "?"), {"ok": False, "detail": "unknown_gmail_action:%s" % (a or "?")}
    args = {k: v for k, v in args.items() if v is not None}
    try:
        import nx_channel_tools as _nct
        return a, _nct._call_dispatch("google_workspace", {"name": "gmail_crud"}, args)
    except Exception as _e:
        return a, {"ok": False, "detail": "gmail_error:%s" % type(_e).__name__}


