def _calendar_action_dispatch(_ga):
    """Map a `calendar` tool call (action + params) to the /api/personal/google-calendar op and dispatch it.
    Returns (action, result). Fake-proof: delegates to nx_channel_tools._call_dispatch, which trusts only the
    route's {ok} envelope, so an un-deployed route is honest-pending, never a fabricated success."""
    _ga = _ga if isinstance(_ga, dict) else {}
    a = str(_ga.get("action") or "").strip().lower()
    cid = _ga.get("calendar_id") or "primary"
    eid = _ga.get("event_id")
    if a in ("schedule", "create", "create_event"):
        args = {"op": "create", "calendarId": cid, "summary": _ga.get("summary"),
                "description": _ga.get("description"), "location": _ga.get("location"),
                "start": _ga.get("start"), "end": _ga.get("end"), "attendees": _ga.get("attendees"),
                "recurrence": _ga.get("recurrence")}
