def _google_chat_action_dispatch(_ga):
    """Map a `google_chat` tool call (action + params) to the /api/personal/google-chat op and dispatch it. Returns
    (action, result). Fake-proof: delegates to nx_channel_tools._call_dispatch (trusts only the route's {ok}
    envelope — un-deployed route is honest-pending, never a fabricated success)."""
    _ga = _ga if isinstance(_ga, dict) else {}
    a = str(_ga.get("action") or "").strip().lower()
    if a in ("spaces_list", "list_spaces", "spaces"):
        args = {"op": "spaces_list", "filter": _ga.get("filter"), "pageSize": _ga.get("max"),
                "pageToken": _ga.get("page_token")}
    elif a in ("space_get", "get_space"):
        args = {"op": "space_get", "name": _ga.get("name")}
    elif a in ("space_create", "create_space"):
        args = {"op": "space_create", "displayName": _ga.get("display_name"), "spaceType": _ga.get("space_type"),
                "description": _ga.get("description"), "guidelines": _ga.get("guidelines"),
                "externalUserAllowed": _ga.get("external_user_allowed")}
    elif a in ("space_update", "update_space"):
        args = {"op": "space_update", "name": _ga.get("name"), "displayName": _ga.get("display_name"),
                "description": _ga.get("description"), "guidelines": _ga.get("guidelines")}
    elif a in ("space_setup", "setup_space"):
        args = {"op": "space_setup", "displayName": _ga.get("display_name"), "spaceType": _ga.get("space_type"),
                "description": _ga.get("description"), "memberNames": _ga.get("member_names"),
                "groupNames": _ga.get("group_names")}
    elif a in ("messages_list", "list_messages"):
        args = {"op": "messages_list", "parent": _ga.get("parent"), "filter": _ga.get("filter"),
                "orderBy": _ga.get("order_by"), "showDeleted": _ga.get("show_deleted"),
                "pageSize": _ga.get("max"), "pageToken": _ga.get("page_token")}
    elif a in ("message_get", "get_message"):
        args = {"op": "message_get", "name": _ga.get("name")}
    elif a in ("message_create", "create_message", "send"):
        args = {"op": "message_create", "parent": _ga.get("parent"), "text": _ga.get("text"),
                "threadName": _ga.get("thread_name"), "threadKey": _ga.get("thread_key"),
                "messageReplyOption": _ga.get("message_reply_option"), "messageId": _ga.get("message_id")}
    elif a in ("message_update", "update_message"):
        args = {"op": "message_update", "name": _ga.get("name"), "text": _ga.get("text"),
                "allowMissing": _ga.get("allow_missing")}
    elif a in ("message_delete", "delete_message"):
        args = {"op": "message_delete", "name": _ga.get("name"), "force": _ga.get("force")}
    elif a in ("members_list", "list_members"):
        args = {"op": "members_list", "parent": _ga.get("parent"), "filter": _ga.get("filter"),
                "showInvited": _ga.get("show_invited"), "pageSize": _ga.get("max"),
                "pageToken": _ga.get("page_token")}
    elif a in ("member_get", "get_member"):
        args = {"op": "member_get", "name": _ga.get("name")}
    elif a in ("member_create", "create_member", "add_member"):
        args = {"op": "member_create", "parent": _ga.get("parent"), "userName": _ga.get("user_name"),
                "groupName": _ga.get("group_name"), "role": _ga.get("role")}
    elif a in ("reactions_create", "create_reaction", "react"):
        args = {"op": "reactions_create", "parent": _ga.get("parent"), "unicode": _ga.get("unicode"),
                "customEmojiUid": _ga.get("custom_emoji_uid")}
    else:
        return (a or "?"), {"ok": False, "detail": "unknown_google_chat_action:%s" % (a or "?")}
    args = {k: v for k, v in args.items() if v is not None}
    try:
        import nx_channel_tools as _nct
        return a, _nct._call_dispatch("google_workspace", {"name": "google_chat_crud"}, args)
    except Exception as _e:
        return a, {"ok": False, "detail": "google_chat_error:%s" % type(_e).__name__}


def _google_meet_action_dispatch(_ga):
    """Map a `google_meet` tool call (action + params) to the /api/personal/google-meet op and dispatch it. Returns
    (action, result). Fake-proof: delegates to nx_channel_tools._call_dispatch (trusts only the route's {ok}
    envelope — un-deployed route is honest-pending, never a fabricated success)."""
    _ga = _ga if isinstance(_ga, dict) else {}
    a = str(_ga.get("action") or "").strip().lower()
    crid = _ga.get("conference_record_id")
    if a in ("space_get", "get_space"):
        args = {"op": "space_get", "spaceId": _ga.get("space_id")}
    elif a in ("space_create", "create_space"):
        args = {"op": "space_create", "accessType": _ga.get("access_type"),
                "entryPointAccess": _ga.get("entry_point_access")}
