def _build_help(groups):
    _CMDW = 22
    _desc = fg(150, 150, 150)
    out = ["", f"  {WHITE_FG}NX — commands{RESET}", ""]
    for header, cmds in groups:
        out.append(f"  {dim(header)}")
        for cmd, desc in cmds:
            out.append(f"    {GOLD_FG}{cmd:<{_CMDW}}{RESET}{_desc}{desc}{RESET}")
        out.append("")
    out.append(f"  {dim('WORLDS')}")
    out.append(f"    {_desc}/worlds switches context — cowork · sales · research · … (28 total){RESET}")
    out.append("")
    out.append(f"  {dim('─── end of commands ───')}")
    out.append("")
    return "\n".join(out)

