def _run_brain(cfg):
    """`/brain` — the operator's live company context (the Brain). Fetches the REAL graph over the device-flow
    bearer (/api/user-brain/graph-cli, the CLI twin of the cookie-authed web read), prints a per-region summary,
    then offers to open the full web Brain. Owner-scoped; empty for a fresh account (NO synthetic seed)."""
    token = cfg.get("token")
    if not token:
        print(dim("  Sign in to see your Brain (see /who)."))
        return
    d = {}
    try:
        import nx_cloud_dispatch as _cd
        _st, d = _cd._req("GET", f"{AUTH_BASE}/api/user-brain/graph-cli", token)
    except Exception:
        d = {}
    nodes = d.get("nodes") or [] if isinstance(d, dict) else []
    from collections import defaultdict
    by_region = defaultdict(list)
    for n in nodes:
        by_region[str((n or {}).get("region") or "other")].append(n)
    print()
    print("  " + gold("Your Brain") + dim("   ·   live company context"))
    print()
    if not nodes:
        print("  " + dim("Empty so far — it fills the instant you connect a tool, save to memory, or run work."))
    else:
        try:
            import shutil as _sh
            _cols = max(60, _sh.get_terminal_size((88, 24)).columns)
        except Exception:
            _cols = 88
        _barw = 10
        _labw = max(18, _cols - 2 - 13 - 4 - _barw - 6)     # width left for the sample labels
        _max = max((len(v) for v in by_region.values()), default=1) or 1
        # Biggest regions first — a scannable hierarchy with a proportional bar, not a flat dump.
        for r in sorted(by_region.keys(), key=lambda k: -len(by_region[k])):
            items = by_region[r]
            n = len(items)
            _fill = max(1, min(_barw, round(n / _max * _barw)))
            bar = gold("▇" * _fill) + (" " * (_barw - _fill))
            # Deduped, whitespace-collapsed sample labels, cleanly ellipsized (never a mid-word cut).
            seen = []
            for i in items:
                lab = " ".join(str((i or {}).get("label") or "").split())
                if lab and lab.lower() not in {s.lower() for s in seen}:
                    seen.append(lab)
                if len(seen) >= 4:
                    break
            labels = "  ·  ".join(seen)
            if len(labels) > _labw:
                labels = labels[:_labw - 1].rstrip(" ·") + "…"
            print("  " + gold("%-13s" % r[:13]) + dim("%4d" % n) + "  " + bar + "  " + dim(labels))
        print()
        print("  " + dim("%d nodes  ·  %d regions — your account" % (len(nodes), len(by_region))))
    web = AUTH_BASE.replace("://api.", "://www.") if "://api." in AUTH_BASE else AUTH_BASE
    # The REAL brain is the Desk's living neural map (BrainSurface, the same graph this command
    # reads), reached via ?world=brain — the CANONICAL destination the web itself redirects the
    # retired /intelligence/brain entry to (summonWorld). NOT the stale /intelligence/brain/
    # cockpit the old link pointed at.
    brain_url = web.rstrip("/") + "/design-a?world=brain"
    print()
    print("  " + dim("Open your Brain on the web →  ") + brain_url)
    try:
        ans = input("  " + gold("open in browser? [y/N] › ")).strip().lower()
    except (EOFError, KeyboardInterrupt):
        print()
        return
    if ans in ("y", "yes"):
        import webbrowser, os as _osb
        # The external browser-opener (e.g. a Codespace's Node `$BROWSER` helper) prints its OWN
        # noise to stderr — a `url.parse()` DeprecationWarning that reads as a dump in the terminal.
        # It isn't ours. Silence stderr at the fd level around the open; the spawned browser process
        # inherits the devnull'd fd 2, so its async warning is swallowed too. Best-effort: if fd
        # redirection fails we still open, just unsilenced.
        _sav = _dn = None
        try:
            _dn = _osb.open(_osb.devnull, _osb.O_WRONLY); _sav = _osb.dup(2); _osb.dup2(_dn, 2)
        except Exception:
            _sav = None
        try:
            webbrowser.open(brain_url); _opened = True
        except Exception:
            _opened = False
        finally:
            try:
                if _sav is not None: _osb.dup2(_sav, 2)
            except Exception:
                pass
            for _fd in (_dn, _sav):
                try:
                    if _fd is not None: _osb.close(_fd)
                except Exception:
                    pass
        print(dim("  Opened.") if _opened else dim("  Couldn't open a browser — copy the link above."))
    print()


# ── /supply — give an agent its OWN channel + send AS that agent ─────────────
# Send-as-agent: each agent gets its own sending identity (like a real hire's work
# email). Handles + non-secret config live in ~/.nx/agent-channels/<slug>.json; the
# sending secret (SMTP app-password / bot token / Twilio token) goes to the Keychain
# under agent-<key>-<secret>, never the json. Email is REAL today (BYOK SMTP).
def _send_as_agent_email(from_addr, host, port, pwd, to, subject, text,
                         in_reply_to=None, references=None, agent_tag=None):
    """Send an email FROM the agent's own address (send-as-agent) via BYOK SMTP+STARTTLS.
    agent_tag stamps an `X-NX-Agent` header so the inbound listener (nx_inbox) can tell OUR
    own mail from a human's and never answer itself — the loop-safety marker. in_reply_to /
    references thread a reply into the original conversation."""
    import smtplib
    from email.mime.text import MIMEText
    msg = MIMEText(text)
    msg["Subject"] = subject
    msg["From"] = from_addr
    msg["To"] = to
    if agent_tag:
        msg["X-NX-Agent"] = str(agent_tag)
    if in_reply_to:
        msg["In-Reply-To"] = in_reply_to
        msg["References"] = references or in_reply_to
    with smtplib.SMTP(host, int(port), timeout=20) as s:
        s.starttls()
        s.login(from_addr, pwd)
        s.sendmail(from_addr, [to], msg.as_string())


def _session_can_compose(cfg):
    """True when the operator's session can actually run a turn — i.e. the access token is present
    AND not expired. An API key counts on its own. Used to REFUSE dispatch rather than send agents
    on duty that read every message and answer none (the failure looks identical to 'ignored you')."""
    if cfg.get("api_key"):
        return True
    tok = str(cfg.get("token") or "").strip()
    if not tok:
        return False
    try:
        import base64, json as _j
        parts = tok.split(".")
        if len(parts) < 2:
            return True                       # opaque token — can't judge; let the send path decide
        pad = "=" * (-len(parts[1]) % 4)
        exp = int(_j.loads(base64.urlsafe_b64decode(parts[1] + pad)).get("exp", 0))
        return (not exp) or exp > int(time.time()) + 30
    except Exception:
        return True                           # undecodable → don't block on a parsing guess


def _agent_email_answer(cfg, agent_key, agent_name, subject, body, notification=False):
    """Generate what the agent writes for an inbound email — the normal NX turn, in the agent's
    voice and home world.

    notification=False → a REPLY to a PERSON: answer them directly.
    notification=True  → this was an automated alert (GitHub/CI/monitoring). The agent must NOT
      write back to the bot; it briefs the OPERATOR: what happened, why, and the next action.
    Returns plain prose (no headers/signature), or "" if nothing was produced."""
    try:
        import nx_agents
        world = nx_agents.AGENT_WORLD.get(agent_key, "cowork")
    except Exception:
        nx_agents, world = None, "cowork"
    rr = None
    try:
        rr = route(world, body, user_id=cfg.get("nx_user_id") or "anonymous")
    except Exception:
        rr = None
    try:
        persona = nx_agents.agent_persona(agent_key) if nx_agents else f"You are {agent_name}."
    except Exception:
        persona = f"You are {agent_name}."
    if notification:
        sysmsg = (persona + f"\n\nYou are {agent_name}. What follows is an AUTOMATED NOTIFICATION "
                  "(GitHub / CI / monitoring), NOT a person writing to you. You are NOT replying to the "
                  "sender — you are briefing YOUR OPERATOR about it. Write a short alert TO THE OPERATOR: "
                  "(1) one line on what happened, (2) the likely cause, (3) the concrete next action they "
                  "should take. Address the operator directly ('you'), never the bot. Plain prose — no "
                  "subject line, no headers, no signature, no quoting.")
        user = f"Automated notification received.\nSubject: {subject}\n\n{body}"
    else:
        sysmsg = (persona + f"\n\nYou are {agent_name}, replying to an EMAIL from a person. Answer the "
                  "message directly and usefully in plain prose — no subject line, no email headers, no "
                  "signature block, no quoting their message back. Keep it tight.")
        user = (f"Subject: {subject}\n\n{body}" if subject else body)
    msgs = [{"role": "system", "content": sysmsg},
            {"role": "user", "content": user}]
    out = []
    try:
        for ch in stream_chat(msgs, cfg,
                              model=(rr.model if rr else None),
                              provider=(rr.provider if rr else None)):
            if ch:
                out.append(ch)
    except Exception:
        return ""
    return "".join(out).strip()


def _run_listen(cfg, once=False, poll_s=20, confirm=True):
    """Foreground inbound loop: poll every agent that has an email or Telegram channel and, for each
    new human message, answer AS that agent and reply (email threaded / Telegram bot). Ctrl-C to stop.
    The receive half of /supply — the agent becomes reachable like a coworker you email or DM.

    confirm=True shows the ⚠ DISPATCH warning + an interactive y/N gate (the `/takeoff` command).
    The DAEMON and any headless/one-shot caller pass confirm=False — they have no TTY, and the
    explicit `nx daemon start` / call IS the consent; prompting there would just EOF and never run."""
    import time as _t
    try:
        import nx_inbox
    except Exception as _e:
        print(dim(f"\n  Inbound email unavailable: {str(_e)[:80]}\n")); return
    binds = [b for b in _load_user_items("agent-channels")
             if (b.get("channels") or {}).get("email") or (b.get("channels") or {}).get("telegram")]
    if not binds:
        print(dim("\n  No agent has an email or Telegram channel yet — /supply first.\n")); return
    if not (cfg.get("token") or cfg.get("nx_session_token") or cfg.get("nx_token")):
        print(dim("\n  Sign in first (run `nx` / `/login`) — the agent needs your session to compose replies.\n")); return
    # PREFLIGHT the session. A token can EXIST but be expired/unrefreshable — dispatching then
    # looks fine but every reply silently comes back empty ("read your message, said nothing").
    # Refuse loudly here instead: agents that can't speak must never be sent on duty.
    try:
        cfg = refresh_token_if_needed(cfg) or cfg
    except Exception:
        pass
    if not _session_can_compose(cfg):
        print(dim("\n  ⚠ Your NX session is expired, so agents could read messages but never answer."))
        print(gold("  Run  nx login  ") + dim("(one sign-in), then /takeoff again.\n"))
        return
    # Honor the operator's web /takeoff selection. If they curated who's on duty on the web, dispatch
    # exactly that set here; if the web shows nothing on duty OR is unreachable, fall back to every supplied
    # binding (today's behavior) rather than silently narrowing who answers on a transient read.
    try:
        import nx_message as _nmsg_duty
        _web_duty = _nmsg_duty.fetch_web_duty()
    except Exception:
        _web_duty = None
    if _web_duty:
        _before_n = len(binds)
        binds = [b for b in binds
                 if any((str(b.get("name")), _c) in _web_duty for _c in ("email", "telegram"))]
        if not binds:
            print(dim("\n  Your web selection matches no channel supplied on this machine — nothing to dispatch here.\n")); return
        print(dim(f"  Honoring your web /takeoff selection: {len(binds)} of {_before_n} agent(s).\n"))
    # Only re-read the web each cycle when the operator is actually CURATING duty there. A pure-CLI operator
    # (never took off on the web) has an empty/None web set — for them the loop must dispatch all local
    # binds as it always has, never idle on an empty web set they never populated.
    _honor_web = bool(_web_duty)
    _kinds = set()
    for _b in binds:
        _kinds |= set(_b.get("channels") or {})
    _duty = " + ".join(k for k in ("email", "telegram") if k in _kinds) or "message"
    if confirm:
        # ⚠ DISPATCH WARNING — this sends real messages on the operator's behalf, autonomously. Say
        # so plainly and get an explicit yes before a single message goes out. Interactive only —
        # the daemon (confirm=False) never reaches this (no TTY → it would just EOF and never run).
        print(gold(f"\n  ⚠  DISPATCH — you are putting agents on live {_duty} duty."))
        print(dim("  " + "─" * 58))
        for b in binds:
            _chs = b.get("channels") or {}
            _bits = []
            if _chs.get("email"):
                _bits.append(f"email {(_chs['email'] or {}).get('handle','?')}")
            if _chs.get("telegram"):
                _bits.append("telegram bot")
            print(gold(f"     {b.get('display') or b.get('name')}") + dim("   " + " · ".join(_bits)))
        print(dim("\n  While running, without asking you each time, they will:"))
        print(dim("     · read new messages on those channels"))
        print(dim("     · REPLY to real people — real email / real Telegram messages, sent as you"))
        print(dim("     · for automated alerts (CI, monitoring, any system): alert YOU with the fix, never reply to the bot"))
        print(dim("  Ctrl-C stops it. Nothing sends until you confirm.\n"))
        try:
            _go = input(gold("  Dispatch? ") + dim("[y/N] › ")).strip().lower()
        except (KeyboardInterrupt, EOFError):
            print(dim("\n  Cancelled — nothing dispatched.\n")); return
        if _go not in ("y", "yes"):
            print(dim("  Cancelled — nothing dispatched.\n")); return
    who = ", ".join((b.get("display") or b.get("name")) for b in binds)
    print(gold(f"\n  ✦ ACTIVE — {who} on live {_duty} duty.") + dim("  Ctrl-C to stop.\n"))
    replied = 0
    _sent_tally = {}      # (agentKey, channel) -> messages this agent has sent this session
    _reported = {}        # (agentKey, channel) -> count last reported to the server
    _stood = set()        # agents announced as stood-down-on-web, so the notice prints once, not each cycle
    # Tell the web these are actually on duty now (delta 0 marks dispatched without inventing a send count).
    try:
        import nx_message as _nmsg_rep
        _nmsg_rep.report_duty([{"agentId": b.get("name"), "channel": _c, "sent": 0}
                               for b in binds for _c in ("email", "telegram")
                               if (b.get("channels") or {}).get(_c)])
    except Exception:
        pass
    try:
        while True:
            # Reload + refresh the session each cycle so a long-running daemon keeps a live token
            # (the CLI session otherwise decays in ~2h) and picks up a fresh `nx login` without a restart.
            try:
                _fresh = load_config()
                if _fresh:
                    cfg = refresh_token_if_needed(_fresh)
            except Exception:
                pass
            # Live web duty: when the operator curates duty on the web, re-read it each cycle so a Stand
            # down there stops this running loop within one poll — not only on restart. None = unreachable
            # this cycle → keep answering the current set (fail-open; never stop a working agent on a blip).
            _live = None
            if _honor_web:
                try:
                    import nx_message as _nmsg_live
                    _live = _nmsg_live.fetch_web_duty()
                except Exception:
                    _live = None
            for b in binds:
                key = b.get("name")
                display = b.get("display") or key
                if _honor_web and _live is not None:
                    if not any((str(key), _c) in _live for _c in ("email", "telegram")):
                        if key not in _stood:
                            print(dim(f"  · {display}: stood down on the web — no longer answering"))
                            _stood.add(key)
                        continue
                    if key in _stood:
                        print(gold(f"  · {display}: back on duty (web)"))
                        _stood.discard(key)
                # ── TELEGRAM leg: answer people who message the agent's bot ──────────────
                tg = (b.get("channels") or {}).get("telegram") or {}
                if tg.get("handle"):
                    try:
                        from nx_channels import kc_get as _kcg
                        _tok = _kcg(_agent_kc(key, "telegram-token"))
                    except Exception:
                        _tok = None
                    if _tok:
                        _first_run = tg.get("offset") is None
                        try:
                            _msgs, _next = nx_inbox.fetch_telegram_new(_tok, tg.get("offset"))
                        except Exception:
                            _msgs, _next = [], tg.get("offset")
                        if _first_run and len(_msgs) > 1:
                            # Coming on shift: Telegram hands back up to ~24h of backlog. Answer the
                            # LATEST message only — firing a reply at every queued message would spam
                            # the chat. The rest are acknowledged (offset advances) and noted honestly.
                            print(dim(f"  · {display}: {len(_msgs) - 1} older message(s) skipped — answering the latest"))
                            _msgs = _msgs[-1:]
                        for _m in _msgs:
                            print(dim(f"  · {display} ← {_m['who']} (telegram): {_m['text'][:48]}"))
                            _ans = _agent_email_answer(cfg, key, display, "", _m["text"])
                            if not _ans:
                                print(dim("    (nothing produced — skipped)")); continue
                            try:
                                _send_as_agent_telegram(_tok, _m["chat_id"], _ans)
                                replied += 1
                                _sent_tally[(key, "telegram")] = _sent_tally.get((key, "telegram"), 0) + 1
                                print(gold(f"    ✓ {display} replied on Telegram to {_m['who']}"))
                            except Exception as _e:
                                print(dim(f"    ✗ telegram reply failed: {str(_e)[:100]}"))
                        # persist the offset so each message is answered exactly once
                        if _next != tg.get("offset"):
                            tg["offset"] = _next
                            b.setdefault("channels", {})["telegram"] = tg
                            try:
                                _save_user_item("agent-channels", b)
                            except Exception:
                                pass
                # ── EMAIL leg ────────────────────────────────────────────────────────────
                ch = (b.get("channels") or {}).get("email") or {}
                addr, host, port = ch.get("handle"), ch.get("host"), ch.get("port") or 587
                if not (addr and host):
                    continue
                try:
                    from nx_channels import kc_get
                    pwd = kc_get(_agent_kc(key, "email-pass"))
                except Exception:
                    pwd = None
                if not pwd:
                    continue
                try:
                    incoming = nx_inbox.fetch_new(host, 993, addr, pwd)
                except Exception:
                    incoming = []
                for m in incoming:
                    frm, subj, body = m["from_addr"], (m["subject"] or "(no subject)"), m["body"]
                    if not (frm and body.strip()):
                        continue
                    is_note = bool(m.get("is_notification"))
                    print(dim(f"  · {display} ← {frm}: {subj[:52]}") + (dim("  [notification]") if is_note else ""))
                    ans = _agent_email_answer(cfg, key, display, subj, body, notification=is_note)
                    if not ans:
                        print(dim("    (nothing produced — skipped)")); continue
                    if is_note:
                        # AUTOMATED alert (GitHub/CI/monitoring): never write back to the bot — brief the
                        # OPERATOR with what happened + the next action, sent to their own address.
                        to_addr = (cfg.get("account") or "").strip() or addr
                        out_subj = f"[{display}] Action needed — {subj}"[:180]
                        out_body = (f"{ans}\n\n— {display} · triggered by an automated notification from {frm}\n"
                                    f"(You're getting this because {display} watches {addr}; it did not reply to the sender.)")
                        try:
                            _send_as_agent_email(addr, host, port, pwd, to_addr, out_subj, out_body, agent_tag=key)
                            replied += 1
                            _sent_tally[(key, "email")] = _sent_tally.get((key, "email"), 0) + 1
                            print(gold(f"    ⚠ {display} alerted YOU ({to_addr}) — did not reply to the bot"))
                        except Exception as _e:
                            print(dim(f"    ✗ alert failed: {str(_e)[:100]}"))
                        continue
                    resubj = subj if subj.lower().startswith("re:") else f"Re: {subj}"
                    try:
                        _send_as_agent_email(addr, host, port, pwd, frm, resubj, ans,
                                             in_reply_to=m["message_id"], references=m["references"], agent_tag=key)
                        replied += 1
                        _sent_tally[(key, "email")] = _sent_tally.get((key, "email"), 0) + 1
                        print(gold(f"    ✓ {display} replied to {frm}"))
                    except Exception as _e:
                        print(dim(f"    ✗ reply failed: {str(_e)[:100]}"))
            # Report real send counts so the web Activity mirrors what actually went out — deltas since the
            # last report, so a restart never clobbers stored history. Best-effort; never interrupts duty.
            _deltas = [{"agentId": _k[0], "channel": _k[1], "sent": _v - _reported.get(_k, 0)}
                       for _k, _v in _sent_tally.items() if _v > _reported.get(_k, 0)]
            if _deltas:
                try:
                    import nx_message as _nmsg_cyc
                    _nmsg_cyc.report_duty(_deltas)
                    _reported = dict(_sent_tally)
                except Exception:
                    pass
            if once:
                return {"replied": replied}
            _t.sleep(max(5, int(poll_s)))
    except KeyboardInterrupt:
        print(dim(f"\n  Off shift. {replied} repl{'y' if replied == 1 else 'ies'} sent this session.\n"))
        return {"replied": replied, "stopped": "interrupt"}


def _run_listen_daemon():
    """Headless entry the OS service runs (`nx __listen-daemon`). Never fast-exits — so launchd /
    systemd don't hot-restart — it waits for a login and an email agent, then runs the listen loop,
    re-entering with a short backoff if it ever returns/errs. Output is captured to ~/.nx/daemon.log.

    Session: each cycle attempts a token refresh via the rotating refresh token
    (refresh_token_if_needed). While the refresh token is valid the daemon stays live with no manual
    `nx login`; if the refresh token is invalid/expired the refresh 401s and a fresh `nx login` IS
    required — that is logged clearly (never a silent failure) rather than pretended-fresh.

    NX_DAEMON_DRYRUN=1 → prove the service loads/runs WITHOUT touching the mailbox (no IMAP fetch, no
    send, no marking mail read). Used to verify the launchd/systemd install safely."""
    import os as _os
    import time as _t
    dry = bool(_os.environ.get("NX_DAEMON_DRYRUN"))
    print(f"[nx daemon] starting — nx {VERSION}{' (dry-run — no fetch/send)' if dry else ''}", flush=True)
    while True:
        try:
            cfg = load_config()
            if not cfg or not (cfg.get("token") or cfg.get("api_key")):
                print("[nx daemon] not signed in — waiting (run `nx login`).", flush=True)
                _t.sleep(60); continue
            try:
                cfg = refresh_token_if_needed(cfg) or cfg
                if cfg.get("_refresh_failed"):
                    print("[nx daemon] token refresh failed — retrying; run `nx login` if it persists.", flush=True)
            except Exception:
                pass
            binds = [b for b in _load_user_items("agent-channels") if (b.get("channels") or {}).get("email")]
            if not binds:
                print("[nx daemon] no email agent yet — waiting (run /supply → Email).", flush=True)
                _t.sleep(60); continue
            if dry:
                who = ", ".join((b.get("display") or b.get("name")) for b in binds)
                _sess = ("token stale — run `nx login` (replies will fail until then)"
                         if cfg.get("_refresh_failed") else "session refreshed")
                print(f"[nx daemon] dry-run OK — {_sess}; would poll {len(binds)} "
                      f"mailbox(es) ({who}) every 30s. No fetch, no send.", flush=True)
                _t.sleep(30); continue
            _run_listen(cfg, once=False, poll_s=30, confirm=False)   # headless: the `nx daemon start` IS the consent
        except Exception as _e:
            print(f"[nx daemon] loop error: {str(_e)[:200]}", flush=True)
        _t.sleep(15)  # brief backoff before re-entering


def _cli_daemon(args):
    """`nx daemon start|stop|status|logs` — run the /listen engine as a background OS service."""
    try:
        import nx_daemon as _D
    except Exception as _e:
        print(dim(f"\n  Daemon unavailable: {str(_e)[:80]}\n")); return
    sub = (args[1] if len(args) > 1 else "status").strip().lower()
    kind = _D.service_kind()
    if sub in ("start", "on", "enable"):
        binds = [b for b in _load_user_items("agent-channels") if (b.get("channels") or {}).get("email")]
        if not binds:
            print(dim("\n  No agent has an email channel yet — run `nx` → /supply → Email first.\n")); return
        ok, out = _D.install()
        if ok:
            print(gold(f"\n  ✦ Daemon on — {kind} installed + started.") + dim("  Agents answer email 24/7, no terminal needed."))
            print(dim(f"  Logs: {_D.LOG_PATH}   ·   Stop: nx daemon stop   ·   Keep signed in so replies can compose.\n"))
        else:
            print(dim(f"\n  ✗ Couldn't start the daemon:\n     {(out or '').strip()[:300]}\n"))
        return
    if sub in ("stop", "off", "disable"):
        _D.uninstall()
        print(gold("\n  ✦ Daemon off.") + dim("  Agents stop answering email in the background.\n"))
        return
    if sub in ("logs", "log", "tail"):
        t = _D.tail_log(40)
        print("\n" + (t if t.strip() else dim("  (no daemon log yet)")) + "\n")
        return
    running = _D.is_running()
    mark = (GREEN_FG + "● running" + RESET) if running else (DIM + "○ stopped" + RESET)
    print(gold(f"\n  Daemon ({kind}): ") + mark)
    t = _D.tail_log(8)
    if t.strip():
        print(dim("  recent:"))
        for ln in t.strip().splitlines()[-8:]:
            print(dim("    " + ln[:100]))
    print(dim("\n  start: nx daemon start   ·   stop: nx daemon stop   ·   logs: nx daemon logs\n"))


def _agent_channels_slug(key):
    # Capped at 40 so the Keychain service name `agent-<slug>-<secret>` stays within the
    # 64-char cap (nx_channels._safe_kc_name), and so the store filename == the lookup key.
    return (re.sub(r'[^a-z0-9_]', '_', str(key).lower()).strip("_") or "agent")[:40]


def _agent_kc(key, secret_name):
    """Keychain service name for an agent's channel secret — slug-keyed (Keychain-safe)."""
    return f"agent-{_agent_channels_slug(key)}-{secret_name}"


def _store_agent_secret(key, secret_name, value):
    """Store an agent's channel secret in the Keychain. Returns True on success — callers
    MUST warn if False, else a later send silently fails against a falsely-'verified' binding."""
    try:
        from nx_channels import kc_set as _kcset
        return bool(_kcset(_agent_kc(key, secret_name), value))
    except Exception:
        return False


def _load_agent_channels(key):
    """The per-agent channel binding (~/.nx/agent-channels/<slug>.json) for `key`, or None.
    Matches by slug so the filename slug and the lookup always agree (no field/file drift)."""
    _s = _agent_channels_slug(key)
    for it in _load_user_items("agent-channels"):
        if _agent_channels_slug(it.get("name", "")) == _s:
            return it
    return None


def _choose(title, items, current=0):
    """Arrow-key picker for any list — ↑↓ · 1-9 jump · Enter · Esc (same feel as /mode, /effort).
    `items` is a list of (label, hint) tuples, dicts, or plain strings. Returns the selected
    index, or None on cancel. Falls back to a numbered input() when there's no TTY (piped/CI)."""
    opts = []
    for it in (items or []):
        if isinstance(it, (list, tuple)):
            opts.append({"label": str(it[0]), "hint": str(it[1]) if len(it) > 1 else ""})
        elif isinstance(it, dict):
            opts.append({"label": str(it.get("label", "")), "hint": str(it.get("hint", ""))})
        else:
            opts.append({"label": str(it), "hint": ""})
    if not opts:
        return None
    try:
        import sys as _sys
        if _sys.stdin.isatty() and _sys.stdout.isatty():
            from nx_slash_menu import run_choice_menu
            return run_choice_menu(title, opts, current=current)
    except Exception:
        pass
    # Fallback (no TTY): the classic numbered prompt.
    print(gold(f"\n  {title}"))
    for i, o in enumerate(opts, 1):
        print("    " + gold(str(i)) + "  " + o["label"] + (("  " + dim(o["hint"])) if o["hint"] else ""))
    print(gold(f"  choose [1-{len(opts)}] › "), end="", flush=True)
    try:
        idx = int(input("").strip()) - 1
        if 0 <= idx < len(opts):
            return idx
    except Exception:
        pass
    return None


def _agent_roster(cfg):
    """The operator's real, pickable agents, in display order:
      · the 5 canonical crew presets — ALWAYS (a local constant, exactly what /crew shows).
        These are NOT gated on a token or the server 'active/live' flag — that gate is what
        used to hide the whole crew and print "No agents yet" for anyone who hadn't toggled
        a preset live yet.
      · their server-side custom agents (e.g. ezra, nina) when signed in;
      · any locally-authored agents (/create → Agent).
    Deduped by key AND by display name. Returns a list of (key, display)."""
    agents = []
    try:
        import nx_agents
        for k in getattr(nx_agents, "ORDER", []):
            meta = (getattr(nx_agents, "CANONICAL", {}) or {}).get(k)
            if meta:
                agents.append((k, meta[0]))
        _tok = str(cfg.get("token") or cfg.get("nx_session_token") or cfg.get("nx_token") or "").strip()
        if _tok:
            try:
                from nx_obfuscate import AUTH as _AUTH
                _canon, customs = nx_agents._fetch_roster(_AUTH["base"], _tok)
                for c in (customs or []):
                    if c.get("name"):
                        agents.append((str(c.get("agentId") or c.get("name")), c.get("name")))
            except Exception:
                pass
    except Exception:
        pass
    for a in _load_user_items("agents"):
        nm = a.get("name", "agent")
        agents.append((_agent_channels_slug(nm), nm))
    seen_k, seen_d, uniq = set(), set(), []
    for k, d in agents:
        _dl = (d or "").strip().lower()
        if k and k not in seen_k and _dl and _dl not in seen_d:
            seen_k.add(k); seen_d.add(_dl); uniq.append((k, d))
    return uniq


def _pick_agent(cfg):
    """Pick one of the operator's agents (see _agent_roster). Returns (key, display) or None."""
    uniq = _agent_roster(cfg)
    if not uniq:
        print(dim("\n  No agents found — sign in, or /create → Agent first.\n"))
        return None
    idx = _choose("Which agent?", [(d, "") for _k, d in uniq])
    if idx is None:
        print(dim("  · cancelled\n")); return None
    return uniq[idx]


def _pick_or_create_agent(cfg):
    """Like _pick_agent, but NEVER dead-ends: it adds a '＋ New agent' choice, and when
    there are no agents yet it just asks for a name and creates one inline (~/.nx/agents/
    <slug>.json — the same store _pick_agent reads). Returns (key, display), or None only
    on an explicit cancel. This is what lets /supply be channel-FIRST: supply the channel,
    then apply it to an agent you pick or create right here."""
    uniq = _agent_roster(cfg)

    def _create():
        print(gold("\n  Name this agent") + dim("  (e.g. Ezra, Nina — NX sends AS this name)"))
        print(gold("  › "), end="", flush=True)
        try:
            nm = input("").strip()
        except (KeyboardInterrupt, EOFError):
            print(); return None
        if not nm:
            print(dim("  · need a name — cancelled\n")); return None
        try:
            _save_user_item("agents", {"name": nm})
        except Exception:
            pass
        print(gold(f"  ✓ Created {nm}.\n"))
        return (_agent_channels_slug(nm), nm)

    if not uniq:
        print(dim("\n  No agents yet — let's make one for this channel."))
        return _create()
    _opts = [(d, "") for _k, d in uniq] + [("＋ New agent", "create a new one")]
    idx = _choose("Apply to which agent?", _opts)
    if idx is None:
        print(dim("  · cancelled\n")); return None
    if idx == len(uniq):
        return _create()
    return uniq[idx]


# Known email providers → (outgoing server, port, friendly name, where-to-get-an-app-password).
# This is what lets a non-technical operator skip "SMTP host / port" entirely: give us a
# gmail/outlook/yahoo/icloud address and we fill the server in and guide the one password step.
_EMAIL_PROVIDERS = {
    "gmail.com":      ("smtp.gmail.com",         587, "Gmail",   "https://myaccount.google.com/apppasswords"),
    "googlemail.com": ("smtp.gmail.com",         587, "Gmail",   "https://myaccount.google.com/apppasswords"),
    "outlook.com":    ("smtp-mail.outlook.com",  587, "Outlook", "https://account.microsoft.com/security"),
    "hotmail.com":    ("smtp-mail.outlook.com",  587, "Outlook", "https://account.microsoft.com/security"),
    "live.com":       ("smtp-mail.outlook.com",  587, "Outlook", "https://account.microsoft.com/security"),
    "msn.com":        ("smtp-mail.outlook.com",  587, "Outlook", "https://account.microsoft.com/security"),
    "yahoo.com":      ("smtp.mail.yahoo.com",    587, "Yahoo",   "https://login.yahoo.com/account/security"),
    "icloud.com":     ("smtp.mail.me.com",       587, "iCloud",  "https://appleid.apple.com"),
    "me.com":         ("smtp.mail.me.com",       587, "iCloud",  "https://appleid.apple.com"),
    "mac.com":        ("smtp.mail.me.com",       587, "iCloud",  "https://appleid.apple.com"),
}
# Custom domains (victor@nexplora.ai) don't name their host — but their MX records do.
# Google Workspace and Microsoft 365 use the SAME smtp servers as consumer Gmail/Outlook,
# so if a domain's mail is hosted there, we connect the same way (with an app password).
_MX_PROVIDERS = [
    (("aspmx.l.google.com", "googlemail.com", "google.com"),
        ("smtp.gmail.com",        587, "Gmail (Google Workspace)", "https://myaccount.google.com/apppasswords")),
    (("protection.outlook.com", "office365", "outlook.com", "microsoft"),
        ("smtp-mail.outlook.com", 587, "Outlook (Microsoft 365)",  "https://account.microsoft.com/security")),
]
def _domain_mx(domain):
    """Best-effort MX lookup. dnspython first — pure-Python and cross-platform (Windows too);
    then the system resolver (dig → host → nslookup) as a fallback for odd environments.
    Returns the records lowercased, or '' when it can't resolve (offline / blocked)."""
    try:
        import dns.resolver
        _ans = dns.resolver.resolve(domain, "MX", lifetime=6)
        return " ".join(str(_r.exchange).lower() for _r in _ans)
    except Exception:
        pass
    import subprocess
    for _cmd in (["dig", "+short", "MX", domain], ["host", "-t", "MX", domain], ["nslookup", "-type=MX", domain]):
        try:
            _r = subprocess.run(_cmd, capture_output=True, text=True, timeout=6)
            _out = (_r.stdout or "").strip().lower()
            if _out:
                return _out
        except Exception:
            continue
    return ""
def _email_provider(addr):
    """Recognize the email's provider so a non-technical operator never types SMTP settings.
    First the consumer-domain map (instant); then, for a custom domain, an MX lookup that
    catches Google Workspace / Microsoft 365 (victor@nexplora.ai is Gmail — its MX is google)."""
    if "@" not in addr:
        return None
    dom = addr.rsplit("@", 1)[-1].lower()
    hit = _EMAIL_PROVIDERS.get(dom)
    if hit:
        return hit
    mx = _domain_mx(dom)
    if mx:
        for _needles, _settings in _MX_PROVIDERS:
            if any(_n in mx for _n in _needles):
                return _settings
    return None


def _supply_assign_email(cfg):
    """Give an agent its own email — in plain language. Ask which address to send from
    (your own is fine), auto-detect the provider so there's no SMTP jargon for the common
    ones, guide the one app-password step, then apply to an agent, test, and confirm."""
    import getpass as _gp
    print(gold("\n  ✦ Give an agent its own email") + dim("  — it sends from an address you own.\n"))
    print(gold("  Which email should it send from?") + dim("  (your own is perfectly fine — e.g. you@gmail.com)"))
    print(gold("  › "), end="", flush=True)
    try:
        email = input("").strip()
    except (KeyboardInterrupt, EOFError):
        print(); return
    if not email or "@" not in email or "." not in email.split("@")[-1]:
        print(dim("  · that doesn't look like an email address — cancelled\n")); return
    _dom0 = email.rsplit("@", 1)[-1].lower()
    if _dom0 not in _EMAIL_PROVIDERS:
        print(dim(f"  checking {_dom0}…"))   # custom domain → MX lookup (may take a moment)
    prov = _email_provider(email)
    if prov:
        _host, _port, _plabel, _pwurl = prov
        print(dim(f"\n  Recognized {_plabel} — I'll connect to it for you, no server settings needed."))
        print(gold(f"  {_plabel} needs a one-time “app password”") + dim(" — your normal password won't work here (that's their security rule):"))
        print(dim(f"     1. open   {_pwurl}"))
        print(dim( "     2. create one and name it “NX”"))
        print(dim( "     3. copy the code it gives you"))
        _pwd_prompt = f"  Paste the {_plabel} app password (hidden — nothing shows as you type) › "
    else:
        _dom = email.rsplit("@", 1)[-1]
        print(dim(f"\n  I don't recognize {_dom}, so I need its outgoing-mail server."))
        print(dim("  Look up your provider's “SMTP settings” (it's on their help page), then paste below."))
        try:
            print(gold("\n  Outgoing server") + dim("  (e.g. smtp.yourprovider.com)"))
            print(gold("  › "), end="", flush=True)
            _host = input("").strip()
            print(gold("\n  Port") + dim("  [587]"))
            print(gold("  › "), end="", flush=True)
            _port = input("").strip() or "587"
        except (KeyboardInterrupt, EOFError):
            print(); return
        if not _host:
            print(dim("  · need the outgoing server — cancelled\n")); return
        _pwd_prompt = f"  Password (or app-password) for {email} (hidden) › "
    try:
        pwd = _gp.getpass(_pwd_prompt)
    except (KeyboardInterrupt, EOFError):
        print(); return
    if not pwd:
        print(dim("  · need the password — cancelled\n")); return
    if prov:
        pwd = "".join(pwd.split())   # app passwords are SHOWN with spaces (e.g. "wwvd qprs qdhk abvs") — SMTP wants them removed
    else:
        pwd = pwd.strip()
    _port = int(_port) if str(_port).isdigit() else 587
    # APPLY — pick or create the agent this channel belongs to (never dead-ends).
    picked = _pick_or_create_agent(cfg)
    if not picked:
        return
    key, display = picked
    stored = _store_agent_secret(key, "email-pass", pwd)
    binding = _load_agent_channels(key) or {"name": key, "display": display, "channels": {}}
    binding["display"] = display
    binding.setdefault("channels", {})
    binding["channels"]["email"] = {"handle": email, "host": _host, "port": _port, "verified": None}
    _save_user_item("agent-channels", binding)
    if not stored:
        print(dim("  ⚠ Couldn't save the password to your Keychain — the test may work now, but later sends won't. Fix Keychain access + re-run.\n"))
    to = email
    print(gold(f"\n  Testing — sending a quick email from {email} to itself…"))
    try:
        _send_as_agent_email(email, _host, _port, pwd, to,
                             f"NX · {display} setup test",
                             f"This is {display}. My email {email} is set up in NX — I can send as {display}.",
                             agent_tag=key)
        if stored:
            binding["channels"]["email"]["verified"] = datetime.date.today().isoformat()
            _save_user_item("agent-channels", binding)
            print(gold(f"  ✓ Sent — check {to}.") + dim(f"  {display} can now send email from {email}.\n"))
        else:
            print(gold(f"  ✓ Sent — check {to}.") + dim("  Re-run once Keychain saves the password so future sends work.\n"))
    except Exception as _e:
        _hint = (f"make the app password while signed in AS {email} itself (not another Google account), then re-run") if prov else "double-check the server, port, and password, then re-run"
        print(dim(f"  ✗ Couldn't send: {str(_e)[:140]}\n     Saved — {_hint}.\n"))


# ── Which Keychain secret each supplied channel owns ────────────────────────
# ONE list, read by both the assign path (which writes the secret) and /revoke (which deletes it). It used
# to exist only inside _supply_revoke, as a literal dict written when there were four channels — so when
# discord and x were added, revoke silently stopped clearing their tokens and left a live bot token in the
# operator's Keychain for a channel they had just taken away. A second hand-maintained list is a list that
# will not be maintained; this is the only one.
#
# None means the channel has NO per-agent secret. That is the honest state for every publishing
# destination: the operator connects the platform ONCE via /publish and /supply binds a destination to an
# agent, so there is no per-agent token to delete — and revoking must not imply it removed a credential it
# never held.
_AGENT_CHANNEL_SECRET = {
    "email":     "email-pass",
    "telegram":  "telegram-token",
    "sms":       "twilio-token",
    "whatsapp":  "twilio-token",       # overridden to whatsapp-meta-token when provider == "meta"
    "imessage":  None,                 # sends from the operator's own signed-in Mac
    "discord":   "discord-token",
    "x":         "x-token",
    "facebook":  None,
    "instagram": None,
    "linkedin":  None,
    "tiktok":    None,
    "youtube":   None,
    "pinterest": None,
}


def _supply_active(cfg):
    """List every agent that has a channel + its handles (verified vs untested)."""
    binds = [b for b in _load_user_items("agent-channels") if (b.get("channels") or {})]
    if not binds:
        print(dim("\n  No agents have channels yet — /supply → a channel to assign one.\n")); return
    print(gold("\n  ACTIVE — agents + their channels"))
    for b in binds:
        print(gold(f"    {b.get('display') or b.get('name')}"))
        for ch, meta in (b.get("channels") or {}).items():
            mark = "✓ verified" if meta.get("verified") else "· untested"
            print("       " + dim(f"{ch:<9} {meta.get('handle','')}   {mark}"))
    print()


def _supply_revoke(cfg):
    """Remove a channel from an agent (keeps the agent; clears its per-agent secret)."""
    binds = [b for b in _load_user_items("agent-channels") if (b.get("channels") or {})]
    if not binds:
        print(dim("\n  Nothing to revoke.\n")); return
    idx = _choose("Revoke — which agent?", [((b.get("display") or b.get("name")), "") for b in binds])
    if idx is None:
        print(dim("  · cancelled\n")); return
    b = binds[idx]
    chans = list((b.get("channels") or {}).keys())
    cidx = _choose(f"Which channel of {b.get('display') or b.get('name')}?", [(ch, "") for ch in chans])
    if cidx is None:
        print(dim("  · cancelled\n")); return
    ch = chans[cidx]
    try:
        from nx_channels import kc_delete as _kcdel
        _sec = _AGENT_CHANNEL_SECRET.get(ch)
        # WhatsApp secret depends on which provider was set up (Meta uses its own token).
        if ch == "whatsapp" and ((b.get("channels") or {}).get("whatsapp") or {}).get("provider") == "meta":
            _sec = "whatsapp-meta-token"
        if _sec:
            _kcdel(_agent_kc(b['name'], _sec))
    except Exception:
        pass
    del b["channels"][ch]
    if b["channels"]:
        _save_user_item("agent-channels", b)
    else:
        try:
            (Path.home() / ".nx" / "agent-channels" / f"{_agent_channels_slug(b['name'])}.json").unlink()
        except Exception:
            pass
    print(gold(f"  ✓ Removed {ch} from {b.get('display') or b.get('name')}.") + dim("  The agent stays on your crew.\n"))


def _send_as_agent_telegram(token, chat_id, text):
    """Post AS the agent's own Telegram bot (operator-supplied per-agent bot token)."""
    r = requests.post(f"https://api.telegram.org/bot{token}/sendMessage",
                      json={"chat_id": chat_id, "text": text}, timeout=20)
    if r.status_code != 200:
        raise RuntimeError(f"telegram {r.status_code}: {r.text[:120]}")


def _send_as_agent_twilio(sid, tok, from_num, to, text, whatsapp=False):
    """Send AS the agent from the operator's own Twilio number (BYOK). Returns the Twilio SID."""
    frm = ("whatsapp:" + from_num) if whatsapp else from_num
    dst = ("whatsapp:" + to) if whatsapp else to
    r = requests.post(f"https://api.twilio.com/2010-04-01/Accounts/{sid}/Messages.json",
                      data={"From": frm, "To": dst, "Body": text[:1500]}, auth=(sid, tok), timeout=20)
    if r.status_code not in (200, 201):
        raise RuntimeError(f"twilio {r.status_code}: {r.text[:160]}")
    try:
        return r.json().get("sid")
    except Exception:
        return None


# A returned SID means Twilio QUEUED the message, NOT that it was delivered. These are why a
# "sent" text never arrives — Twilio reports them as error_code on the message status.
_TWILIO_ERR = {
    "30034": "your US number isn't registered for A2P 10DLC — US carriers block unregistered 10-digit senders. Register a campaign in the Twilio console (Messaging → Regulatory Compliance → A2P 10DLC).",
    "30035": "A2P 10DLC campaign is pending approval — not live yet.",
    "30032": "the number isn't provisioned/verified for messaging.",
    "30007": "the carrier filtered it as spam — change the content or use a registered number.",
    "21608": "on a Twilio TRIAL account you can only text VERIFIED numbers — verify this number in the console (or upgrade the account).",
    "21211": "that recipient isn't a valid phone number.",
    "21606": "the 'from' number isn't SMS-capable — use a real Twilio SMS number.",
    "21612": "this number/route can't reach that destination.",
}


def _twilio_message_status(sid, tok, msg_sid, tries=6, gap=2):
    """Poll a Twilio message toward a terminal state. Returns (status, error_code, error_message).
    status ∈ queued|sending|sent|delivered|undelivered|failed. Best-effort — never raises."""
    import time as _t
    st, ec, em = "queued", None, None
    for _ in range(max(1, tries)):
        try:
            r = requests.get(f"https://api.twilio.com/2010-04-01/Accounts/{sid}/Messages/{msg_sid}.json",
                             auth=(sid, tok), timeout=15)
            if r.status_code == 200:
                d = r.json()
                st = d.get("status") or st
                ec = d.get("error_code")
                em = d.get("error_message")
                if st in ("delivered", "undelivered", "failed"):
                    break
        except Exception:
            pass
        _t.sleep(gap)
    return st, (str(ec) if ec is not None else None), em


def _imessage_self_handles():
    """The operator's OWN iMessage-capable handles on this Mac (their iCloud account id), so the
    recipient can be PICKED instead of typed. Best-effort + read-only; [] if unavailable."""
    import subprocess, re as _re
    out = []
    try:
        r = subprocess.run(["defaults", "read", "MobileMeAccounts", "Accounts"],
                           capture_output=True, text=True, timeout=8)
        for _id in _re.findall(r'AccountID = "([^"]+)"', r.stdout or ""):
            if _id and _id not in out:
                out.append(_id)
    except Exception:
        pass
    return out


def _valid_imessage_handle(v):
    """A real iMessage target: an email, or a phone number. Anything else (e.g. the word
    'imessage') is refused BEFORE we hand it to Messages — an invalid handle otherwise sails
    through AppleScript and only fails later as a macOS 'Message Failed to Send' banner."""
    import re as _re
    v = (v or "").strip()
    if _re.match(r"^[^@\s]+@[^@\s]+\.[A-Za-z]{2,}$", v):
        return True
    digits = _re.sub(r"[^0-9]", "", v)
    return bool(_re.match(r"^\+?[0-9][0-9\s().\-]{6,}$", v)) and 7 <= len(digits) <= 15


_PRIV_PANES = {
    # macOS System Settings deep-links — jump straight to the exact privacy pane, no hunting.
    "full-disk": ("Full Disk Access", "x-apple.systempreferences:com.apple.preference.security?Privacy_AllFiles"),
    "automation": ("Automation", "x-apple.systempreferences:com.apple.preference.security?Privacy_Automation"),
}


def _offer_permission(kind, why, done_hint):
    """Offer to OPEN the exact macOS permission pane (y/N) instead of telling the operator to hunt
    for a toggle. Opens System Settings deep-linked to that pane on yes. macOS only; no-op elsewhere."""
    import sys as _sys
    if _sys.platform != "darwin":
        return
    label, url = _PRIV_PANES.get(kind, (kind, ""))
    print(dim("\n  " + why))
    try:
        g = input(gold(f"  Open {label} settings now? ") + dim("[Y/n] › ")).strip().lower()
    except (KeyboardInterrupt, EOFError):
        g = "n"
    if g in ("", "y", "yes"):
        try:
            import subprocess
            subprocess.run(["open", url], timeout=8)
            print(dim(f"  → Opened {label}. {done_hint}\n"))
        except Exception:
            print(dim(f"  → Couldn't open it — System Settings → Privacy & Security → {label}. {done_hint}\n"))
    else:
        print(dim(f"  · Skipped — grant it later in Privacy & Security → {label}.\n"))


def _send_as_agent_imessage(to, text, from_account=None):
    """Send via Messages.app. from_account = the agent's DEDICATED Apple ID; the message goes out
    from THAT iMessage account, not the Mac's default (personal) one. If that account isn't signed
    into Messages we ERROR rather than fall back to your personal identity — sending as the wrong
    person is worse than not sending.

    HONESTY: AppleScript hands the message to Messages and returns; delivery is asynchronous, so a
    0 exit code means "accepted for sending", NOT "delivered". Callers phrase it as handed-off."""
    import sys
    if sys.platform != "darwin":
        raise RuntimeError("iMessage is macOS-only — use Email, Telegram, or SMS on this device.")
    if not _valid_imessage_handle(to):
        raise RuntimeError(f"“{str(to)[:40]}” isn't a phone number or email — Messages can't deliver to it.")
    import subprocess
    acct = (from_account or "").strip()
    # {msg, h, acctId} — acctId "" → default account; otherwise the iMessage account whose id
    # carries that Apple ID (Messages account ids embed the handle, e.g. "iMessage;-;a@icloud.com").
    script = (
        'on run {msg, h, acctId}\n'
        '  tell application "Messages"\n'
        '    if acctId is "" then\n'
        '      set svc to (1st account whose service type = iMessage)\n'
        '    else\n'
        '      set matches to (every account whose service type = iMessage and id contains acctId)\n'
        '      if (count of matches) is 0 then error "nx-acct-not-signed-in"\n'
        '      set svc to item 1 of matches\n'
        '    end if\n'
        '    try\n'
        '      send msg to buddy h of svc\n'
        '    on error\n'
        '      send msg to participant h of svc\n'
        '    end try\n'
        '  end tell\n'
        'end run')
    r = subprocess.run(["osascript", "-e", script, text, str(to), acct], capture_output=True, text=True, timeout=20)
    if r.returncode != 0:
        err = (r.stderr or "osascript failed")
        if "nx-acct-not-signed-in" in err:
            raise RuntimeError(f"the agent's Apple ID “{acct}” isn't signed into Messages on this Mac — "
                               f"sign it in (Messages → Settings → iMessage), then re-run.")
        raise RuntimeError("imessage: " + err[:140])


def _supply_assign_telegram(cfg):
    """Give an agent its OWN Telegram bot (operator's @BotFather token) + prove it posts as the agent."""
    import getpass as _gp
    print(gold("\n  ✦ Give an agent its own Telegram bot") + dim("  — a free account it posts from.\n"))
    print(dim("  Make one in about a minute:"))
    print(dim("     1. in Telegram, search   @BotFather"))
    print(dim("     2. send   /newbot   and pick a name"))
    print(dim("     3. it replies with a token — paste it below (hidden)"))
    try:
        print(gold("\n  Bot token") + dim("  (hidden — paste what @BotFather gave you)"))
        token = _gp.getpass("  › ").strip()
    except (KeyboardInterrupt, EOFError):
        print(); return
    if not token:
        print(dim("  · need the bot token — cancelled\n")); return
    # A token is "<bot_id>:<secret>" — the number BEFORE the colon is the BOT's own account id.
    # Operators naturally paste that when asked for a "chat id", and Telegram then answers
    # "the bot can't send messages to the bot". So: verify the token, then WAIT for them to tap
    # Start and read the chat id ourselves. Nobody should have to hunt for a number.
    _bot_id = token.split(":", 1)[0].strip()

    # 1. Verify the token (getMe) — fail loudly here rather than at the test-send.
    _bot_user = ""
    try:
        _me = requests.get(f"https://api.telegram.org/bot{token}/getMe", timeout=15).json()
        if not _me.get("ok"):
            print(dim(f"\n  ✗ Telegram rejected that token ({_me.get('description','invalid')}).")
                  + dim("  Copy it again from @BotFather — cancelled.\n")); return
        _bot_user = (_me.get("result") or {}).get("username") or ""
    except Exception as _e:
        print(dim(f"\n  ✗ Couldn't reach Telegram: {str(_e)[:80]} — cancelled.\n")); return
    _handle = ("@" + _bot_user) if _bot_user else "your bot"
    print(gold(f"\n  ✓ Token works — {_handle} is live."))

    def _poll_updates():
        """Newest chat that messaged the bot → (chat_id, who). ('__conflict__', None) if a webhook
        is hijacking updates (getUpdates 409), else (None, None)."""
        try:
            _r = requests.get(f"https://api.telegram.org/bot{token}/getUpdates", timeout=15).json()
            if not _r.get("ok") and _r.get("error_code") == 409:
                return "__conflict__", None
            for _u in reversed(_r.get("result", []) or []):
                _chat = ((_u.get("message") or _u.get("channel_post") or {}).get("chat")) or {}
                if _chat.get("id") and str(_chat.get("type")) != "bot":
                    _who = (_chat.get("title") or " ".join(x for x in [_chat.get("first_name"), _chat.get("last_name")] if x)
                            or _chat.get("username") or "your chat")
                    return str(_chat["id"]), _who
        except Exception:
            pass
        return None, None

    # 2. WAIT for the operator to tap Start — poll, don't interrogate.
    print(gold(f"\n  Now open {_handle} in Telegram and tap Start") + dim("  (or send it any message)."))
    print(dim("  Waiting… I'll pick up the chat automatically.  Ctrl-C to enter one by hand."))
    chat_id = who = None
    try:
        import time as _t
        for _i in range(45):                    # ~90s of patience
            chat_id, who = _poll_updates()
            if chat_id == "__conflict__":
                print(dim("\n  ✗ This bot has a webhook set, so I can't read its messages.")
                      + dim("  Remove it (deleteWebhook) or use another bot — cancelled.\n")); return
            if chat_id:
                print(gold(f"  ✓ Found it — {who}.")); break
            _t.sleep(2)
    except KeyboardInterrupt:
        print()
    # 3. Manual fallback — and REFUSE the bot's own id (the token-prefix mistake).
    if not chat_id:
        print(dim("\n  I didn't see a message yet."))
        print(dim(f"  Tip: it must be YOUR chat with {_handle} — not the number from the token."))
        for _try in range(3):
            print(gold("  Press Enter to look again") + dim("  (or paste a chat id / @channel):"))
            try:
                _v = input(gold("  › ")).strip()
            except (KeyboardInterrupt, EOFError):
                print(); return
            if not _v:
                chat_id, who = _poll_updates()
                if chat_id and chat_id != "__conflict__":
                    print(gold(f"  ✓ Found it — {who}.")); break
                print(dim("  · still nothing — tap Start in Telegram first.")); continue
            if _v.lstrip("-").isdigit() and _v == _bot_id:
                print(dim("  · that's the BOT's own id (the number before the “:” in your token)."))
                print(dim("    I need YOUR chat with it — just tap Start and press Enter.")); continue
            if _v.lstrip("-").isdigit() or (_v.startswith("@") and len(_v) > 1 and " " not in _v):
                chat_id = _v; break
            print(dim(f"  · “{_v[:30]}” isn't a chat id — a number (e.g. 123456789) or a channel like @mychannel."))
        if not chat_id or chat_id == "__conflict__":
            print(dim(f"  · couldn't find the chat — tap Start in {_handle}, then re-run /supply.\n")); return
    # APPLY — pick or create the agent this channel belongs to.
    picked = _pick_or_create_agent(cfg)
    if not picked:
        return
    key, display = picked
    stored = _store_agent_secret(key, "telegram-token", token)
    binding = _load_agent_channels(key) or {"name": key, "display": display, "channels": {}}
    binding["display"] = display; binding.setdefault("channels", {})
    binding["channels"]["telegram"] = {"handle": chat_id, "verified": None}
    _save_user_item("agent-channels", binding)
    if not stored:
        print(dim("  ⚠ Couldn't save the bot token to your Keychain — later sends won't work until you re-run.\n"))
    print(gold(f"  Testing — {display}'s bot is messaging {chat_id}…"))
    try:
        _send_as_agent_telegram(token, chat_id, f"This is {display}. My Telegram bot is live in NX — I can message as {display}.")
        if stored:
            binding["channels"]["telegram"]["verified"] = datetime.date.today().isoformat()
            _save_user_item("agent-channels", binding)
        print(gold(f"  ✓ Sent — check Telegram, posted as {display}'s bot.") + dim("  Verified.\n" if stored else "  Re-run so Keychain saves the token.\n"))
    except Exception as _e:
        _es = str(_e)
        _hint = ("the bot can't see that chat — open the bot in Telegram and tap Start, then re-run"
                 if "chat not found" in _es.lower() else "check the token / chat id, then re-run to verify")
        print(dim(f"  ✗ Test failed: {_es[:140]}\n     Saved — {_hint}.\n"))


def _send_as_agent_whatsapp_meta(phone_number_id, token, to, text):
    """Send a WhatsApp text via Meta's WhatsApp Cloud API (Graph). Free-form text only delivers
    inside the 24-hour customer-service window; outside it Meta requires an approved template."""
    _to = re.sub(r"[^0-9]", "", str(to))     # Meta wants digits only, no '+'
    r = requests.post(
        f"https://graph.facebook.com/v20.0/{phone_number_id}/messages",
        headers={"Authorization": "Bearer " + token, "Content-Type": "application/json"},
        json={"messaging_product": "whatsapp", "to": _to, "type": "text", "text": {"body": text[:1000]}},
        timeout=20,
    )
    if r.status_code >= 300:
        raise RuntimeError(f"meta whatsapp {r.status_code}: {(r.text or '')[:200]}")


def _supply_assign_whatsapp(cfg):
    """WhatsApp — the operator PICKS how to send: Meta's WhatsApp Cloud API (direct, if they have a
    WhatsApp Business account) or Twilio (a provider). No assumption that they lack a Meta account."""
    print(gold("\n  ✦ Give an agent a WhatsApp number") + dim("  — a WhatsApp BUSINESS number (WhatsApp has no personal API).\n"))
    _pi = _choose("How does it send WhatsApp?", [
        ("Meta — WhatsApp Cloud API", "direct, if you have a WhatsApp Business account"),
        ("Twilio", "a provider — quick sandbox, no Meta review"),
    ])
    if _pi is None:
        print(dim("  · cancelled\n")); return
    if _pi == 0:
        _supply_assign_whatsapp_meta(cfg)
    else:
        _supply_assign_twilio(cfg, whatsapp=True)


