                        for _onm, (_oslug, _oworlds, _odesc) in _NX_OAUTH.items():
                            _menu_reg.setdefault(_onm, {
                                "worlds": _oworlds, "tools_count": 0, "tier": "oauth",
                                "description": _odesc, "slug": _oslug,
                            })
                        chosen=run_integrations_menu(_menu_reg,world)
                        if not chosen:
                            continue
                        # The menu now returns a connector SLUG (not the display label). Build the slug-keyed
                        # routing sets so every pick lands on its CORRECT connect path:
                        #   remote MCP server (DCR sign-in)  ·  backend-OAuth  ·  personal connector (/api/oauth/initiate)
                        try:
                            import nx_tool_manifest as _ntmc
                            _mani_conns = (_ntmc.load_manifest() or {}).get("connectors") or []
                            _manifest_slugs = {c.get("provider", "") for c in _mani_conns if c.get("provider")}
                            _manifest_auth = {c.get("provider", ""): (c.get("auth") or "byok")
                                              for c in _mani_conns if c.get("provider")}
                        except Exception:
                            _manifest_slugs, _manifest_auth = set(), {}
                        _nxoauth_by_slug = {v[0]: (k, v) for k, v in _NX_OAUTH.items()}
                        try:
                            import nx_mcp_oauth as _mcpo_r
                            def _is_remote(_s):
                                try: return bool(_mcpo_r.is_remote_mcp(_s))
                                except Exception: return False
                        except Exception:
                            def _is_remote(_s): return False
                        # A channel was picked → route to the channels connect flow.
                        try:
                            import nx_channels as _chsel
                            if chosen in _chsel.REGISTRY:
                                import getpass as _gp2
                                _psc=lambda l: _gp2.getpass(f"  {fg(*GOLD_DIM)}{l} ❯{RESET} ").strip()
                                print(_chsel.handle_command(["connect", chosen], prompt_secret=_psc))
                                continue
                        except Exception:
                            pass
                        # A Nexplora commerce connector → connect via the web business-os
                        # OAuth (opens the browser; one account, global thereafter).
                        if chosen in _NX_COMMERCE:
                            import webbrowser as _wb
                            _opened=False; _oauth_url=None
                            # Preferred: NX is signed in → an authed call returns the platform's
