import os as _os_tree
# per-TREE ceiling (2c) — env-tunable so an operator can raise/lower the swarm's resource budget (and so it's testable).
_TREE_MAX_DISPATCH = int(_os_tree.environ.get("NX_TREE_MAX_DISPATCH", "6") or 6)    # total sub-agents across the tree
_TREE_MAX_TOOLCALLS = int(_os_tree.environ.get("NX_TREE_MAX_TOOLCALLS", "40") or 40)  # total tool executions across the tree
_TREE_DEADLINE_SECS = int(_os_tree.environ.get("NX_TREE_DEADLINE_SECS", "360") or 360)  # wall-clock ceiling for the tree


def _cli_agent(key, task, as_json=False, success="", _depth=0, _approve=False, _tree=None):
    """Non-interactive crew-agent run:  nx --agent vinny "check my revenue"

    Routes through the SAME path as the interactive /vinny — the agent persona + its forced home world + its
    DOMAIN-scoped connected tools + the native function-calling loop (capped at 3 rounds) — so the agent READS
    and WRITES the operator's real integrations. Prints the tool-call trace (↪ lines = real reads/writes) and
    the agent's answer. Returns the answer text (so a LEADER can dispatch a researcher sub-agent and use it).
    _depth: 0 = a leader (may dispatch researchers); >0 = a sub-agent (gets NO dispatch tool → depth=1 cap)."""
    import time as _t, json as _json
    try:
        from nx_agents import (agent_persona as _apersona, AGENT_WORLD as _aworlds,
                               agent_slugs as _aslugs, CANONICAL as _canon,
                               RESEARCHERS as _researchers, ORDER as _leaders)
    except Exception as _e:
        print_error(f"agent module load failed: {_e}"); return ""
    key = (key or "").lstrip("/").lower()
    if key not in _aworlds:
        print_error(f"unknown agent '{key}'. one of: {', '.join(_aworlds)}"); return
    if not (task or "").strip():
        print(gold(f"  Usage: nx --agent {key} \"<task>\"")); return

    cfg = load_config()
    if cfg:
        try: cfg = refresh_token_if_needed(cfg)
        except Exception: pass
    if not cfg or not (cfg.get("token") or cfg.get("api_key")):
        print(gold("  Not signed in. Run `nx` once to authenticate.")); return

    name = _canon.get(key, (key.title(), ""))[0]
    world = _aworlds.get(key, "cowork")
    # Per-turn agent injection — mirrors the REPL dispatch exactly.
    cfg["_noninteractive"] = True   # one-shot / --agent / auto-delegate
    cfg["_approve_ok"] = bool(_approve)   # --approve: ENABLES operational mode ('I'm present, prompt me PER-OP') — NOT blanket
    # A dispatched sub-agent (_depth>0) NEVER inherits the operator's destructive pre-auth — collision guarantee (2d):
    # it stays read-only (search scope) and can't fire destructive, so many sub-agents on related records can't corrupt.
    if _depth > 0:
        cfg["_approve_ok"] = False
    cfg["_swarm_depth"] = _depth    # 0 = leader (may dispatch); >0 = sub-agent (no dispatch tool → depth=1 cap)
    # Per-TREE resource ceiling (2c) — a SHARED budget threaded through the whole leader→sub-agent tree. The leader
    # (depth 0) creates it; every dispatched sub-agent decrements the SAME pool, so a runaway tree is halted no
    # matter which actor is burning resources. Also carries the tree PROVENANCE (2f) — every op → its actor.
    if _tree is None:
        _tree = {"dispatch": 0, "toolcalls": 0, "deadline": _t.time() + _TREE_DEADLINE_SECS, "prov": [], "halted": None}

    def _tree_ok(kind):
        """True if the tree may do one more op of `kind` ('dispatch'|'tool'). Sets _tree['halted'] on breach."""
        if _tree.get("halted"):
            return False
        if _t.time() > _tree["deadline"]:
            _tree["halted"] = "tree_deadline"; return False
        if kind == "dispatch" and _tree["dispatch"] >= _TREE_MAX_DISPATCH:
            _tree["halted"] = "max_dispatch"; return False
        if kind == "tool" and _tree["toolcalls"] >= _TREE_MAX_TOOLCALLS:
            _tree["halted"] = "max_toolcalls"; return False
        return True
    cfg["_agent_persona"] = _apersona(key)
    if (success or "").strip():
        cfg["_success_criterion"] = success.strip()   # operator-set "done well" — injected via _augment_system_prompt
    cfg["_agent_world"]   = world     # resolve_route_result pops this → forces the home world
    cfg["_agent_turn"]    = True
    cfg["_agent_key"]     = key

    print(gold(f"\n  ✦ {name}"))
    print(dim(f"  {task}\n"))
    started = _t.time()

    try:
        result = resolve_route_result(cfg, world, task)
        prompt = build_system_prompt(world=result.world, voice=result.voice)
        prompt = _augment_system_prompt(cfg, prompt)   # pops _agent_persona → appends it
        if _depth == 0 and key in _leaders:
            # Leaders don't browse/web-search themselves — they DISPATCH a research sub-agent (text-tag form, the
            # call shape the model actually emits) that returns cited facts. Researchers do the reading; leaders act.
            prompt += ("\n\nRESEARCH DISPATCH: you do NOT web-search or scrape yourself. When you need EXTERNAL "
                       "facts — about a company, market, person, or a claim to verify — dispatch a research "
                       "sub-agent by emitting EXACTLY this tag:  <nx:dispatch researcher=\"scout\" task=\"the "
                       "research question\"/>  . Researchers: scout (general web research) · scan (competitor/"
                       "market) · verify (fact-check with sources) · watch (news/monitoring) · enrich (company/lead "
                       "firmographics). The sub-agent returns cited facts; use them in your answer. Dispatch when "
                       "you lack the facts; don't guess and don't ask the operator to look it up.")
        if key == "enrich":
            prompt += ("\n\nPDL ENRICHMENT: for firmographic/contact facts, query People Data Labs by emitting "
                       "EXACTLY:  <nx:pdl kind=\"company\" query=\"company name or domain\"/>  (or kind=\"person\" "
                       "with a name or email). PDL returns REAL data or found:false — report ONLY what it returns, "
                       "never invent a size, industry, employee count, or contact. You may also tavily-search for "
                       "context, but the firmographics come from PDL.")

        # DOMAIN-scoped tools (the fix): agent gets its ROLE's connected integrations, not the all-24 blob.
        _native_tools, _scope = None, []
        try:
            import nx_mcp_tools as _mt
            if _mt.any_connected():
                _scope = _aslugs(key, _mt.connected_slugs())
                _native_tools = _mt.tools_schema(slugs=_scope) if _scope else None
        except Exception:
            _native_tools = None
        if _scope:
            print(dim(f"  ⚙ {name.lower()}'s tools: {len(_native_tools or [])} across {len(_scope)} integrations "
                      f"({', '.join(sorted(_scope)[:8])}{'…' if len(_scope) > 8 else ''})\n"))
        # SWARM: a LEADER at depth 0 gets ONE extra tool — dispatch a safe-ops researcher sub-agent. A sub-agent
        # (_depth > 0) never receives it, so a worker structurally cannot spawn a worker → depth = 1 is enforced by
        # construction (no runtime counter to bypass), and the sub-agent is RiskTier-SAFE by its search-only scope.
        if _depth == 0:  # top-level agent can send from the operator's OWN Gmail (sub-agents stay safe-ops/read-only)
            _native_tools = (_native_tools or []) + [_GMAIL_SEND_TOOL, _GMAIL_TOOL,
                                                     _CALENDAR_TOOL, _DRIVE_TOOL, _DOCS_TOOL, _SHEETS_TOOL,
                                                     _GOOGLE_CHAT_TOOL, _GOOGLE_MEET_TOOL, _GOOGLE_FORMS_TOOL, _GOOGLE_TASKS_TOOL,
                                                     _NOTION_TOOL, _DROPBOX_TOOL, _AIRTABLE_TOOL,
                                                     _CONFLUENCE_TOOL, _BOX_TOOL, _ONEDRIVE_TOOL,
                                                     _CODA_TOOL, _SHAREPOINT_TOOL, _OUTLOOK_TOOL, _OUTLOOK_CALENDAR_TOOL, _TEAMS_TOOL, _EXCEL_TOOL, _WORD_TOOL, _POWERPOINT_TOOL, _ONENOTE_TOOL, _BOOKINGS_TOOL, _SMARTSHEET_TOOL,
                                                     _JIRA_TOOL, _LINEAR_TOOL, _MONDAY_TOOL,
                                                     _ASANA_TOOL, _TRELLO_TOOL, _ZOOM_TOOL,
                                                     _MIRO_TOOL, _HEIGHT_TOOL, _YOUTRACK_TOOL,
                                                     _GITHUB_TOOL, _GITLAB_TOOL, _VERCEL_TOOL,
                                                     _CLOUDFLARE_TOOL, _SUPABASE_TOOL, _NETLIFY_TOOL,
                                                     _SENTRY_TOOL, _PAGERDUTY_TOOL, _LAUNCHDARKLY_TOOL,
                                                     _ATLAS_TOOL, _PLANETSCALE_TOOL, _NEON_TOOL,
                                                     _DIGITALOCEAN_TOOL, _FLY_TOOL, _RENDER_TOOL,
                                                     _RAILWAY_TOOL, _HEROKU_TOOL, _NEWRELIC_TOOL,
                                                     _DATADOG_TOOL, _GRAFANA_TOOL, _OPSGENIE_TOOL,
                                                     _SNOWFLAKE_TOOL, _DATABRICKS_TOOL, _BIGQUERY_TOOL,
                                                     _SERVICENOW_TOOL, _TERRAFORM_TOOL, _UPSTASH_TOOL,
                                                     _BITBUCKET_TOOL, _CIRCLECI_TOOL, _SPLIT_TOOL,
                                                     _ANTHROPIC_TOOL, _OPENAI_TOOL, _MISTRAL_TOOL, _COHERE_TOOL, _HUGGINGFACE_TOOL,
                                                     _GEMINI_TOOL, _REPLICATE_TOOL, _ELEVENLABS_TOOL, _TOGETHER_TOOL,
                                                     _GROQ_TOOL, _OPENROUTER_TOOL, _STABILITY_TOOL, _FIREWORKS_TOOL,
                                                     _MAILCHIMP_TOOL, _KLAVIYO_TOOL, _SENDGRID_TOOL, _BUFFER_TOOL,
                                                     _STRIPE_TOOL, _SHOPIFY_TOOL, _QUICKBOOKS_TOOL, _XERO_TOOL,
                                                     _AUTH0_TOOL, _OKTA_TOOL, _CLERK_TOOL, _VANTA_TOOL,
                                                     _ZENDESK_TOOL, _INTERCOM_TOOL, _FRESHDESK_TOOL, _FRONT_TOOL,
                                                     _HUBSPOT_TOOL, _SALESFORCE_TOOL, _PIPEDRIVE_TOOL, _POSTHOG_TOOL,
                                                     _FIGMA_TOOL, _GREENHOUSE_TOOL, _DOCUSIGN_TOOL, _DISCORD_TOOL,
                                                     _MIXPANEL_TOOL, _AMPLITUDE_TOOL, _SEGMENT_TOOL, _LEVER_TOOL,
                                                     _CONVERTKIT_TOOL, _CANVA_TOOL, _PULUMI_TOOL, _HOOTSUITE_TOOL,
                                                     _BAMBOOHR_TOOL, _WORKABLE_TOOL, _KOMODOR_TOOL, _BEEHIIV_TOOL,
                                                     _SLACK_TOOL, _TWILIO_TOOL, _CALENDLY_TOOL, _TYPEFORM_TOOL]
            # AUTO-SYNC: any deployed /api/personal/* connector NOT hand-wired above, from the manifest.
            try:
                import nx_tool_manifest as _ntm
                _ntm.ensure_routes()
                _seen_names = {(_t.get("function") or {}).get("name") for _t in (_native_tools or []) if isinstance(_t, dict)}
                _native_tools = (_native_tools or []) + _ntm.manifest_tools(exclude_names=_seen_names)
            except Exception:
                pass
        if _depth == 0 and key in _leaders:
            _native_tools = (_native_tools or []) + [_DISPATCH_RESEARCHER_TOOL]
        # Same de-dup as the main turn path: one canonical, steered tool per connected app.
        _native_tools = _dedup_tool_surface(_native_tools)

        messages = [{"role": "system", "content": prompt},
                    {"role": "user", "content": task}]

        def _stream_once():
            _acc = []
            for _ch in stream_chat(messages, cfg, api_key=result.api_key, model=result.model,
                                   provider=result.provider, extra_body=result.extra_body,
                                   secondary_model=getattr(result, "secondary_model", ""),
                                   tools=_native_tools):
                _acc.append(_ch)
            return "".join(_acc)

        import nx_mcp_tools as _mt
        import nx_harness as _nxh
        messages, _ = _nxh.compact_messages(messages)  # NX HARNESS: bound a long agent transcript before streaming
        assistant = _scrub_identity(_strip_narration(_stream_once()))
        _ntc = [c for c in (cfg.get("_native_tool_calls") or []) if c.get("name")]
        _round, _trace = 0, []
        _nx_streak = {"tool": None, "count": 0}   # NX HARNESS: this run's same-tool failure streak
        # THIS is the real `nx --agent` native loop (_cli_agent — the one-shot dispatch target; the REPL has a
        # separate twin). Operational (--approve) runs get more rounds so a multi-step MUTATE task (create→delete,
        # update→archive) reaches its destructive step instead of being truncated at 3 — the 'created but never
        # deleted' bug. Read-only agent runs AND dispatched sub-agents (_approve_ok forced False at 6663) stay at 3.
        _agent_cap = 6 if cfg.get("_approve_ok") else 3
        _nudged = False   # operational completion nudge fires at most once (below)
        _auth_stopped = False   # set when we short-circuit on a connector auth failure
        while _ntc and _round < _agent_cap and _native_tools:
            _round += 1
            _tc_msg = [{"id": c.get("id") or f"call_{_round}_{i}", "type": "function",
                        "function": {"name": c["name"], "arguments": c.get("arguments") or "{}"}}
                       for i, c in enumerate(_ntc)]
            messages.append({"role": "assistant", "content": (assistant or None), "tool_calls": _tc_msg})
            _trace_start = len(_trace)   # slice THIS round's trace for the auth check
            for i, c in enumerate(_ntc):
                if c["name"] == "dispatch_researcher":
                    # SWARM dispatch — run a researcher as a depth-1 safe-ops sub-agent, hand its facts back up.
                    try: _da = _json.loads(c.get("arguments") or "{}")
                    except Exception: _da = {}
                    _rk = str(_da.get("researcher", "")).strip().lower()
                    _rt = str(_da.get("task", "")).strip()
                    if not _tree_ok("dispatch"):
                        _rans = f"[TREE CEILING reached ({_tree.get('halted')}) — the tree is halted; no more sub-agents]"
                    elif _rk in _researchers and _rt:
                        _tree["dispatch"] += 1
                        print(dim(f"\n  ⇲ {name} → dispatching {_rk} (safe-ops research sub-agent · depth=1 · tree {_tree['dispatch']}/{_TREE_MAX_DISPATCH})"))
                        _rans = _cli_agent(_rk, _rt, _depth=1, _tree=_tree) or "(researcher returned nothing)"
                        _tree["prov"].append({"actor": _rk, "parent": name, "depth": 1, "op": "research"})
                        print(dim(f"  ⇱ {_rk} handed facts back to {name}\n"))
                    else:
                        _rans = f"[dispatch error: researcher must be one of {', '.join(_researchers)} + a real task]"
                    _trace.append({"server": "swarm", "tool": f"dispatch:{_rk or '?'}", "ok": _rk in _researchers,
                                   "args": (c.get("arguments") or "")[:200], "out": (_rans or "")[:400]})
                    messages.append({"role": "tool", "tool_call_id": _tc_msg[i]["id"],
                                     "content": _truncate_tool_output(_rans)})
                    continue
                if c["name"] == "send_gmail" or "send_gmail" in c["name"].lower() or c["name"].lower() in ("send_email", "gmail_send", "send_mail"):
                    # First-party Gmail send from the operator's OWN mailbox — not a zapier/MCP email action.
                    try: _ga = _json.loads(c.get("arguments") or "{}")
                    except Exception: _ga = {}
                    try:
                        import nx_channel_tools as _nct
                        _gres = _nct._call_dispatch("google_workspace", {"name": "gmail_send_message"},
                            {"to": _ga.get("to", ""), "subject": _ga.get("subject", ""), "body": _ga.get("body", "")})
                    except Exception as _e:
                        _gres = {"ok": False, "detail": "gmail_send_error:%s" % type(_e).__name__}
                    _gok = bool(_gres.get("ok"))
                    _gout = _gres.get("text") if _gok else (_gres.get("detail") or "send failed")
                    if not _gok and _gres.get("hint"): _gout = "%s — %s" % (_gout, _gres["hint"])
                    print(dim(f"  ↪ gmail · send {'✓' if _gok else '⚠'} {str(_gout)[:80]}"))
                    _trace.append({"server": "gmail", "tool": "send", "ok": _gok,
                                   "args": (c.get("arguments") or "")[:200], "out": str(_gout)[:400]})
                    messages.append({"role": "tool", "tool_call_id": _tc_msg[i]["id"],
                                     "content": _truncate_tool_output(str(_gout) or ("sent" if _gok else "failed"))})
                    continue
                if c["name"] == "gmail" or c["name"].lower() == "gmail":
                    # Full e2e Gmail — list/read/reply/draft/archive/star/delete/mark/filter on the operator's OWN mailbox.
                    try: _ga = _json.loads(c.get("arguments") or "{}")
                    except Exception: _ga = {}
                    _gact, _gres = _gmail_action_dispatch(_ga)
                    _gok = bool(_gres.get("ok"))
                    _gout = _gres.get("text") if _gok else (_gres.get("detail") or "failed")
                    if not _gok and _gres.get("hint"): _gout = "%s — %s" % (_gout, _gres["hint"])
                    print(dim(f"  ↪ gmail · {_gact} {'✓' if _gok else '⚠'} {str(_gout)[:80]}"))
                    _trace.append({"server": "gmail", "tool": _gact, "ok": _gok,
                                   "args": (c.get("arguments") or "")[:200], "out": str(_gout)[:400]})
                    messages.append({"role": "tool", "tool_call_id": _tc_msg[i]["id"],
                                     "content": _truncate_tool_output(str(_gout) or ("done" if _gok else "failed"))})
                    continue
                # Full e2e Google Workspace — calendar/drive/docs/sheets on the operator's OWN connected account.
                _gw_dispatch = {"calendar": _calendar_action_dispatch, "drive": _drive_action_dispatch,
                                "docs": _docs_action_dispatch, "sheets": _sheets_action_dispatch}
                if c["name"] in _gw_dispatch or c["name"].lower() in _gw_dispatch:
                    _svc = c["name"] if c["name"] in _gw_dispatch else c["name"].lower()
                    try: _ga = _json.loads(c.get("arguments") or "{}")
                    except Exception: _ga = {}
                    _gact, _gres = _gw_dispatch[_svc](_ga)
                    _gok = bool(_gres.get("ok"))
                    _gout = _gres.get("text") if _gok else (_gres.get("detail") or "failed")
                    if not _gok and _gres.get("hint"): _gout = "%s — %s" % (_gout, _gres["hint"])
                    print(dim(f"  ↪ {_svc} · {_gact} {'✓' if _gok else '⚠'} {str(_gout)[:80]}"))
                    _trace.append({"server": _svc, "tool": _gact, "ok": _gok,
                                   "args": (c.get("arguments") or "")[:200], "out": str(_gout)[:400]})
                    messages.append({"role": "tool", "tool_call_id": _tc_msg[i]["id"],
                                     "content": _truncate_tool_output(str(_gout) or ("done" if _gok else "failed"))})
                    continue
                # Bespoke personal connectors — notion/dropbox/airtable/confluence/box/onedrive/coda/sharepoint/smartsheet on the operator's OWN connected account.
                _kd_dispatch = {"notion": _notion_action_dispatch, "dropbox": _dropbox_action_dispatch,
                                "airtable": _airtable_action_dispatch, "confluence": _confluence_action_dispatch,
                                "box": _box_action_dispatch, "onedrive": _onedrive_action_dispatch,
                                "coda": _coda_action_dispatch, "sharepoint": _sharepoint_action_dispatch, "outlook": _outlook_action_dispatch, "outlook_calendar": _outlook_calendar_action_dispatch, "teams": _teams_action_dispatch, "excel": _excel_action_dispatch, "word": _word_action_dispatch, "powerpoint": _powerpoint_action_dispatch, "onenote": _onenote_action_dispatch, "bookings": _bookings_action_dispatch,
                                "smartsheet": _smartsheet_action_dispatch, "jira": _jira_action_dispatch,
                                "linear": _linear_action_dispatch, "monday": _monday_action_dispatch,
                                "asana": _asana_action_dispatch, "trello": _trello_action_dispatch,
                                "zoom": _zoom_action_dispatch, "miro": _miro_action_dispatch,
                                "height": _height_action_dispatch, "youtrack": _youtrack_action_dispatch,
                                "github": _github_action_dispatch, "gitlab": _gitlab_action_dispatch,
                                "vercel": _vercel_action_dispatch, "cloudflare": _cloudflare_action_dispatch,
                                "supabase": _supabase_action_dispatch, "netlify": _netlify_action_dispatch,
                                "sentry": _sentry_action_dispatch, "pagerduty": _pagerduty_action_dispatch,
                                "launchdarkly": _launchdarkly_action_dispatch, "atlas": _atlas_action_dispatch,
                                "planetscale": _planetscale_action_dispatch, "neon": _neon_action_dispatch,
                                "digitalocean": _digitalocean_action_dispatch, "fly": _fly_action_dispatch,
                                "render": _render_action_dispatch, "railway": _railway_action_dispatch,
                                "heroku": _heroku_action_dispatch, "newrelic": _newrelic_action_dispatch,
                                "datadog": _datadog_action_dispatch, "grafana": _grafana_action_dispatch,
                                "opsgenie": _opsgenie_action_dispatch,
                                "snowflake": _snowflake_action_dispatch, "databricks": _databricks_action_dispatch,
                                "bigquery": _bigquery_action_dispatch,
                                "servicenow": _servicenow_action_dispatch, "terraform": _terraform_action_dispatch,
                                "upstash": _upstash_action_dispatch,
                                "bitbucket": _bitbucket_action_dispatch, "circleci": _circleci_action_dispatch,
                                "split": _split_action_dispatch,
                                "anthropic": _anthropic_action_dispatch, "openai": _openai_action_dispatch, "mistral": _mistral_action_dispatch,
                                "cohere": _cohere_action_dispatch, "huggingface": _huggingface_action_dispatch,
                                "gemini": _gemini_action_dispatch, "replicate": _replicate_action_dispatch,
                                "elevenlabs": _elevenlabs_action_dispatch, "together": _together_action_dispatch,
                                "groq": _groq_action_dispatch, "openrouter": _openrouter_action_dispatch,
                                "stability": _stability_action_dispatch, "fireworks": _fireworks_action_dispatch,
                                "mailchimp": _mailchimp_action_dispatch, "klaviyo": _klaviyo_action_dispatch,
                                "sendgrid": _sendgrid_action_dispatch, "buffer": _buffer_action_dispatch,
                                "stripe": _stripe_action_dispatch, "shopify": _shopify_action_dispatch,
                                "quickbooks": _quickbooks_action_dispatch, "xero": _xero_action_dispatch,
                                "auth0": _auth0_action_dispatch, "okta": _okta_action_dispatch,
                                "clerk": _clerk_action_dispatch, "vanta": _vanta_action_dispatch,
                                "zendesk": _zendesk_action_dispatch, "intercom": _intercom_action_dispatch,
                                "freshdesk": _freshdesk_action_dispatch, "front": _front_action_dispatch,
                                "hubspot": _hubspot_action_dispatch, "salesforce": _salesforce_action_dispatch,
                                "pipedrive": _pipedrive_action_dispatch, "posthog": _posthog_action_dispatch,
                                "figma": _figma_action_dispatch, "greenhouse": _greenhouse_action_dispatch,
                                "docusign": _docusign_action_dispatch, "discord": _discord_action_dispatch,
                                "mixpanel": _mixpanel_action_dispatch, "amplitude": _amplitude_action_dispatch,
                                "segment": _segment_action_dispatch, "lever": _lever_action_dispatch,
                                "convertkit": _convertkit_action_dispatch, "canva": _canva_action_dispatch,
                                "pulumi": _pulumi_action_dispatch, "hootsuite": _hootsuite_action_dispatch,
                                "bamboohr": _bamboohr_action_dispatch, "workable": _workable_action_dispatch,
                                "komodor": _komodor_action_dispatch, "beehiiv": _beehiiv_action_dispatch,
                                "google_chat": _google_chat_action_dispatch, "google_meet": _google_meet_action_dispatch,
                                "google_forms": _google_forms_action_dispatch, "google_tasks": _google_tasks_action_dispatch,
                                "slack": _slack_action_dispatch, "twilio": _twilio_action_dispatch,
                                "calendly": _calendly_action_dispatch, "typeform": _typeform_action_dispatch}
                try:  # AUTO-SYNC: dispatch for any manifest connector NOT hand-wired above
                    import nx_tool_manifest as _ntm
                    for _mp, _mfn in _ntm.manifest_dispatch_map(exclude_names=set(_kd_dispatch)).items():
                        _kd_dispatch.setdefault(_mp, _mfn)
                except Exception:
                    pass
                if c["name"] in _kd_dispatch or c["name"].lower() in _kd_dispatch:
                    _ksvc = c["name"] if c["name"] in _kd_dispatch else c["name"].lower()
                    try: _ka = _json.loads(c.get("arguments") or "{}")
                    except Exception: _ka = {}
                    _kact, _kres = _kd_dispatch[_ksvc](_ka)
                    _kok = bool(_kres.get("ok"))
                    _kout = _kres.get("text") if _kok else (_kres.get("detail") or "failed")
                    if not _kok and _kres.get("hint"): _kout = "%s — %s" % (_kout, _kres["hint"])
                    print(dim(f"  ↪ {_ksvc} · {_kact} {'✓' if _kok else '⚠'} {str(_kout)[:80]}"))
                    _trace.append({"server": _ksvc, "tool": _kact, "ok": _kok,
                                   "args": (c.get("arguments") or "")[:200], "out": str(_kout)[:400]})
                    messages.append({"role": "tool", "tool_call_id": _tc_msg[i]["id"],
                                     "content": _truncate_tool_output(str(_kout) or ("done" if _kok else "failed"))})
                    continue
                if not _tree_ok("tool"):
                    _srv, _tl, _res = c["name"], "", {"ok": False, "error": f"TREE CEILING ({_tree.get('halted')}) — halted"}
                else:
                    _tree["toolcalls"] += 1
                    _route = _mt.route_fn(c["name"])
                    if _route:
                        _srv, _tl = _route
                        try: _res = _guarded_mcp_call(_srv, _tl, c.get("arguments") or "{}", cfg)
                        except Exception as _e: _res = {"ok": False, "error": type(_e).__name__}
                    else:
                        _srv, _tl, _res = c["name"], "", {"ok": False, "error": "unknown tool"}
                _ok = bool(_res.get("ok"))
                _out = _res.get("text") if _ok else _res.get("error", "")
                _icn = f"{GREEN_FG}✓{RESET}" if _ok else f"{GOLDD}⚠{RESET}"
                print(f"  {DIM}↪ {_srv} · {_tl or c['name']} {_icn} {_summarize_mcp_output(_out or '', _ok)}{RESET}")
                _trace.append({"server": _srv, "tool": _tl or c["name"], "ok": _ok,
                               "args": (c.get("arguments") or "")[:300], "out": (_out or "")[:400]})
                _tree["prov"].append({"actor": name, "parent": None if _depth == 0 else "leader", "depth": _depth,
                                      "op": f"{_srv}·{_tl or c['name']}", "ok": _ok})
                messages.append({"role": "tool", "tool_call_id": _tc_msg[i]["id"],
                                 "content": _truncate_tool_output(_out or "")})
            # Connector AUTH failure → STOP (agent path). Same rule as the REPL loop: the auth lives
            # in the operator's connection, not on disk — don't let the agent flail hunting for it.
            _prov = _auth_stop_provider(_trace[_trace_start:])   # shared detector
            if _prov:
                messages.append({"role": "user", "content": (
                    "[NX SYSTEM] The %s connection returned an AUTH error — its token is not valid. Do "
                    "NOT run shell commands or hunt for the auth; tell the operator in ONE line to "
                    "reconnect %s (run `/integrations %s`), then stop." % (_prov, _prov, _prov))})
                _af_acc = []  # no-tools final turn → the model can only write the reconnect line
                for _ch in stream_chat(messages, cfg, api_key=result.api_key, model=result.model,
                                       provider=result.provider, extra_body=result.extra_body,
                                       secondary_model=getattr(result, "secondary_model", ""), tools=None):
                    _af_acc.append(_ch)
                assistant = _scrub_identity(_strip_narration("".join(_af_acc))) or _auth_reconnect_line(_prov)
                _auth_stopped = True
                _ntc = []
                break
            # NX HARNESS: between rounds — same-tool failure streak nudge + compact a long transcript.
            messages, _nx_streak = _nxh.apply_between_rounds(messages, _trace[_trace_start:], _nx_streak)
            assistant = _scrub_identity(_strip_narration(_stream_once()))
            _ntc = [c for c in (cfg.get("_native_tool_calls") or []) if c.get("name")]
            # OPERATIONAL COMPLETION NUDGE (once): the model produced a final answer (no more tool calls) but the
            # operator asked for a DESTRUCTIVE action and only reads happened — the 'resolved it, then stopped'
            # failure. Push it to carry the action through; refilling _ntc re-runs THIS loop to execute the op.
            # Bounded by _agent_cap and _nudged; the per-op gate still confirms, so this fixes incompleteness only.
            if (not _ntc and not _nudged and _native_tools and cfg.get("_approve_ok")
                    and _is_destructive_intent(task) and not _destructive_attempted(_trace)):
                _nudged = True
                messages.append({"role": "assistant", "content": assistant or ""})
                messages.append({"role": "user", "content": (
                    "You READ / resolved the target but have NOT performed the destructive action the operator "
                    "explicitly requested. If exactly one record matches, issue the destructive tool call NOW to "
                    "carry it out — it is confirmed per-op before anything runs, so proceeding is correct and safe. "
                    "If several matched, name them with ids and ask which. If none matched, say so plainly. Do NOT "
                    "stop at merely reporting what you found.")})
                assistant = _scrub_identity(_strip_narration(_stream_once()))
                _ntc = [c for c in (cfg.get("_native_tool_calls") or []) if c.get("name")]

        # SWARM DISPATCH (text-tag form — the shape the model actually emits). A leader emitting
        # <nx:dispatch researcher="X" task="…"/> runs that researcher as a depth-1 safe-ops sub-agent and feeds its
        # cited facts back. Researchers never receive the instruction or the tool → depth=1 is structural. Bounded.
        _RX_DISPATCH = _re_tools.compile(
            r"<nx:dispatch\s+researcher=[\"']([a-z]+)[\"']\s+task=[\"'](.*?)[\"']\s*/?>",
            _re_tools.IGNORECASE | _re_tools.DOTALL)
        _dr = 0
        while _depth == 0 and key in _leaders and _RX_DISPATCH.search(assistant or "") and _dr < 3:
            _dr += 1
            _cleaned = assistant
            for _m in list(_RX_DISPATCH.finditer(assistant or "")):
                _rk = (_m.group(1) or "").lower(); _rt = (_m.group(2) or "").strip()
                if not _tree_ok("dispatch"):
                    _facts = f"[TREE CEILING reached ({_tree.get('halted')}) — the tree is halted; no more sub-agents]"
                elif _rk in _researchers and _rt:
                    _tree["dispatch"] += 1
                    print(dim(f"\n  ⇲ {name} → dispatching {_rk} (safe-ops research sub-agent · depth=1 · tree {_tree['dispatch']}/{_TREE_MAX_DISPATCH})"))
                    _facts = _cli_agent(_rk, _rt, _depth=1, _tree=_tree) or "(researcher returned nothing)"
                    _tree["prov"].append({"actor": _rk, "parent": name, "depth": 1, "op": "research"})
                    print(dim(f"  ⇱ {_rk} handed facts back to {name}\n"))
                else:
                    _facts = f"[dispatch error: researcher must be one of {', '.join(_researchers)} + a real task]"
                _cleaned = _cleaned.replace(_m.group(0), f"\n\n«{_rk} researched and returned:\n{_facts}»\n\n")
                _trace.append({"server": "swarm", "tool": f"dispatch:{_rk or '?'}", "ok": _rk in _researchers,
                               "out": (_facts or "")[:400]})
            messages.append({"role": "assistant", "content": _cleaned})
            messages.append({"role": "user", "content": (
                "Your research sub-agent(s) returned the facts above (inside «…»). Give the operator your answer NOW "
                "using those facts and citing the sources the researcher provided. Do NOT dispatch again unless you "
                "genuinely still lack a fact you need.")})
            assistant = _scrub_identity(_strip_narration(_stream_once()))

        # PDL ENRICHMENT (Enrich researcher) — <nx:pdl kind="company|person" query="…"/> → REAL People Data Labs
        # firmographics (key read from env; Claude never handles it). Real data or honest found:false, never invented.
        _RX_PDL = _re_tools.compile(r"<nx:pdl\s+kind=[\"'](company|person)[\"']\s+query=[\"'](.*?)[\"']\s*/?>",
                                    _re_tools.IGNORECASE | _re_tools.DOTALL)
        _pr = 0
        while key == "enrich" and _RX_PDL.search(assistant or "") and _pr < 3:
            _pr += 1
            _cleaned = assistant
            for _m in list(_RX_PDL.finditer(assistant or "")):
                _pk = (_m.group(1) or "company").lower(); _pq = (_m.group(2) or "").strip()
                _pres = _pdl_lookup(_pq, _pk)
                _ptxt = _pres.get("text") if _pres.get("ok") else _pres.get("error", "")
                _icn = f"{GREEN_FG}✓{RESET}" if _pres.get("ok") else f"{GOLDD}⚠{RESET}"
                print(f"  {DIM}↪ pdl · {_pk} {_icn} {_summarize_mcp_output(_ptxt or '', _pres.get('ok'))}{RESET}")
                _cleaned = _cleaned.replace(_m.group(0), f"«PDL {_pk} '{_pq}': {_ptxt}»")
                _trace.append({"server": "pdl", "tool": _pk, "ok": bool(_pres.get("ok")), "out": (_ptxt or "")[:400]})
            messages.append({"role": "assistant", "content": _cleaned})
            messages.append({"role": "user", "content": "Report the PDL result above in prose — ONLY the real fields "
                             "it returned; if found:false or a field is missing, say so plainly. Never invent firmographics."})
            assistant = _scrub_identity(_strip_narration(_stream_once()))

        # Text-tag path — the model often emits <nx:mcp server=… tool=… args=…/> tags instead of native
        # tool_calls (both are valid; the REPL fires either). Execute those too, feed the real results back,
        # and let the agent answer from them — capped at 3 rounds with an anti-flail break.
        _ttr, _unprod = 0, 0
        _ttr_cap = 7 if cfg.get("_approve_ok") else 5   # operational multi-step (create→delete) needs more tag-rounds
        while _has_tool_tags(assistant or "") and _ttr < _ttr_cap and _unprod < 2:
            _ttr += 1
            cleaned, tool_results = _execute_nx_tool_calls(assistant, cfg, approve_fn=_make_command_approver(cfg))
            if not tool_results:
                break
            _unprod = 0 if any(_tr.get("success") for _tr in tool_results) else _unprod + 1
            for _tr in tool_results:
                if _tr.get("tool") == "mcp":
                    _ok = _tr.get("success")
                    _ic = (f"{GREEN_FG}✓{RESET}" if _ok else
                           (f"{GOLDD}⚠ connected{RESET}" if _tr.get("connected") else f"{GOLDD}✗{RESET}"))
                    print(f"  {DIM}↪ {_tr.get('server')} · {_tr.get('name')} {_ic} "
                          f"{_summarize_mcp_output(_tr.get('output') or '', _ok)}{RESET}")
                    _trace.append({"server": _tr.get("server"), "tool": _tr.get("name"),
                                   "ok": bool(_ok), "out": (_tr.get("output") or "")[:400]})
                elif _tr.get("tool") == "run_command":
                    # streaming suppresses run tags — render the "Ran <cmd>" / "└ <output>" block here.
                    _rok = _tr.get("success")
                    _print_run_block(_tr.get("cmd") or "", _tr.get("output") or "", _rok)
                    _trace.append({"server": "shell", "tool": _tr.get("cmd"),
                                   "ok": bool(_rok), "out": (_tr.get("output") or "")[:400]})
            _auth_prov = _auth_stop_provider(tool_results)   # connector auth failure on the text-tag path
            if _auth_prov:
                # STOP before the "retry the tag" nudge below drives a flail — surface reconnect + end.
                assistant = _auth_reconnect_line(_auth_prov)
                _auth_stopped = True
                break
            messages.append({"role": "assistant", "content": cleaned})
            messages.append({"role": "user", "content": (
                "TOOL RESULTS BELOW — answer using ONLY this real data; never invent names, numbers, or records. "
                "If a result errors with a fixable wrong-tool/missing-arg, emit a corrected <nx:mcp .../> and retry "
                "once; otherwise summarize.\n" + _format_tool_results(tool_results))})
            assistant = _scrub_identity(_strip_narration(_stream_once()))

        # Force ONE no-tools summary pass when the turn ended WITHOUT a real answer: raw <nx:mcp/> tags leaked, OR
        # the model ran a tool and stopped so the only text left is the cleaned «ran tool ✓» marker / near-empty
        # (Verify searched then never synthesized). Strip the «…» markers — if <40 chars of real prose remain, the
        # agent must summarize from the tool results it already has instead of leaking the marker as the answer.
        _bare = _re_tools.sub(r"«[^»]*»", "", assistant or "").strip()
        if not _auth_stopped and (_has_tool_tags(assistant or "") or len(_bare) < 40):
            messages.append({"role": "user", "content": (
                "Answer the operator now, in prose, from the tool results above — do NOT emit any tool tags. Lead "
                "with the verdict/answer and cite the real sources you found. If the results don't settle it, say "
                "so plainly ('unverified' / 'not found') and show what you searched. Never invent a fact or source.")})
            _native_tools = None
            assistant = _scrub_identity(_strip_narration(_stream_once())) or assistant

        print()
        print(f"  {gold(name + ':')} {assistant}")
        # TREE PROVENANCE (2f) + ceiling status (2c) — only the ROOT leader prints the whole-tree roll-up, so with
        # many actors the operator still sees, at a glance, which named actor did what and whether a ceiling fired.
        if _depth == 0 and _tree.get("prov"):
            _leaderops = sum(1 for _p in _tree["prov"] if _p.get("depth") == 0)
            _subops = {}
            for _p in _tree["prov"]:
                if _p.get("depth", 0) >= 1 and _p.get("op") != "research":
                    _subops[_p["actor"]] = _subops.get(_p["actor"], 0) + 1
            _line = f"  {DIM}⧉ tree provenance — {name}: {_leaderops} op(s)"
            if _subops:
                _line += " · sub-agents: " + ", ".join(f"{_k} {_v} op(s)" for _k, _v in _subops.items())
            _line += f"  [{_tree['dispatch']}/{_TREE_MAX_DISPATCH} dispatched · {_tree['toolcalls']}/{_TREE_MAX_TOOLCALLS} tool-calls]"
            if _tree.get("halted"):
                _line += f"  ⚠ HALTED by ceiling: {_tree['halted']}"
            print(_line + RESET)
        # grail phase #2 STEP 5 — auto-feed the UNIFIED brain when this run did real work (the CLI 'important'
        # tee: successful execute + substantive output → one node, so the flywheel compounds from CLI usage).
        try:
            _brain_autofeed_agent_run(cfg, name, result.world, task, assistant, _trace, _depth)
        except Exception:
            pass
        if as_json:
            print(_json.dumps({"ok": True, "agent": key, "world": result.world,
                               "tools_in_scope": len(_native_tools or []),
                               "integrations": sorted(_scope), "rounds": _round,
                               "tool_calls": _trace, "latency_ms": int((_t.time() - started) * 1000),
                               "response": assistant}))
        return assistant   # so a leader dispatching this as a sub-agent gets the facts back
    except Exception as e:
        print_error(_sanitize_gateway_error(e))
        return ""


def _run_flight(world, cfg):
    """Flight (the mode-picker action) — run the born-safe autonomy loop end to end on
    the ACTIVE world. Only SAFE reads fire; every T2/T3 stages for approval. Same gate
    as /loop, scoped to one world."""
    try:
        print(gold(f"\n  ✦ Flight — running {world} end to end   ") + dim("(autonomous · gated · reads only)\n"))
        _cli_loop_run([world], dry_run=False, use_llm=True, rounds=1, cfg=cfg)
    except Exception as e:
        print_error("flight: " + str(e))


def print_customize_panel(world, cfg):
    """Customize (the mode-picker action) — NX's 'shape how it works for you' surface in
    the terminal: the personalization knobs, each a real command with its current value."""
    mode = (cfg.get("voice_override") or "").strip()
    try:
        from nx_prompts import normalize_mode as _nm
        mode_label = _nm(mode).title() if mode else "auto (per world)"
    except Exception:
        mode_label = mode or "auto"
    model = (cfg.get("model") or "").strip() or "auto"
    _desc = fg(150, 150, 150)
    rows = (
        ("/mode",         f"how NX reasons — now: {mode_label}"),
        ("/model",        f"which model — now: {model}"),
        ("/worlds",       f"which world — now: {world}"),
        ("/crew",         "your agent crew + build your own"),
        ("/skills",       "your imported skills"),
        ("/integrations", "connect tools & accounts"),
        ("/publish",      "publish out — social + search"),
        ("/channels",     "how NX reaches you — Telegram · WhatsApp · Text · Email"),
        ("/message",      "where NX reports back"),
    )
    print()
    print("  " + gold("Customize") + dim("  — shape how NX works for you"))
    print("  " + dim("─" * 54))
    for cmd, desc in rows:
        print(f"    {GOLD_FG}{cmd:<16}{RESET}{_desc}{desc}{RESET}")
    print("  " + dim("─" * 54))
    print()


def _cli_loop_run(worlds, dry_run=False, use_llm=False, rounds=1, cfg=None):
    """`nx --loop` / `/loop` entry — the born-safe autonomy loop (grail phase #5). Fires T1 reads only, stages
    every T2/T3 for operator approval, reports to Telegram + the shared brain, records to ~/.nx/autonomy_runs.jsonl.
    Firing is DOUBLE-GATED (autonomy_loop.guarded_loop_action + _guarded_mcp_call), so nothing destructive runs."""
    import nx_loop as _nl
    cfg = cfg if cfg is not None else (load_config() or {})
    if not cfg.get("token"):
        print("Sign in first (nx login) to run the autonomy loop.")
        return
    print(("DRY-RUN " if dry_run else "") + "NX autonomy loop → " + str(len(worlds)) + " world(s): " + ", ".join(worlds))
    try:
        _run, _rr, _rec = _nl.cli_loop(cfg, worlds, use_llm=use_llm, dry_run=dry_run, rounds=rounds)
    except Exception as e:
        print("loop error: " + str(e))
        return
    print(_rr.text)
    _c = _rec["counts"]
    print("— fired " + str(_c["fired"]) + " · staged " + str(_c["staged"]) + " · run " + str(_rec["run_id"])[:8] + " —")
    if not dry_run:
        print("report: telegram=" + str(_rr.telegram_sent) + " brain=" + str(_rr.brain_teed))
        if not _rr.delivered:
            print("(no channel delivered — set TELEGRAM_BOT_TOKEN / TELEGRAM_CHAT_ID, or check sign-in)")


def main():
    raw_args=sys.argv[1:]
    use_ui="--ui" in raw_args
    args=[arg for arg in raw_args if arg!="--ui"]

    # Load user-created skills (~/.nx/skills/*.json) into _SKILL_PROMPTS for EVERY entry path — the REPL loaded
    # them later (before its loop), but --prompt/--agent dispatched and returned first, so `nx --prompt … --skill
    # myskill` silently got the generic fallback instead of the real overlay. Idempotent; safe to also run at boot.
    try: _load_bundled_skills_into_prompts()
    except Exception: pass
    try: _load_user_skills_into_prompts()
    except Exception: pass

    if args and args[0] in("-h","--help"):
        show_welcome();print(HELP);return
    if args and args[0]=="--version":
        print(f"nx {VERSION}");return
    if args and args[0]=="run":
        # nx run <id> — resume a specific saved session by the short id shown on its save line.
        if len(args) < 2 or not args[1].strip():
            print(gold("  usage: ") + gold("nx run <id>") + dim("   (the id shown when a session saves)")); return
        if not _prime_resume_from_short_id(args[1]):
            return
        args = []  # fall through to the normal REPL launch; run_nx_repl auto-splices via _RESUME_ON_START
    if args and args[0]=="logout":
        clear_config();print(gold("  ✦ signed out."));return
    if args and args[0]=="who":
        cfg=load_config()
        if not cfg:print(gold("  not signed in. Run `nx login`."))
        else:
            # Audit-I: mask on-screen.
            try:
                from nx_terminal import _mask_email as _maskw
            except Exception:
                _maskw = lambda s: s
            print(gold(f"  ✦ {_maskw(cfg.get('account') or '') or 'Nexplora account'}"))
        return
    if args and args[0]=="export-creds":
        _cli_export_creds(args[1] if len(args)>1 else None)
        return
    if args and args[0]=="__listen-daemon":
        # Headless entry the OS background service runs — reads the operator's session from config,
        # never interactive. (Installed/controlled via `nx daemon`.)
        _run_listen_daemon()
        return
    if args and args[0]=="daemon":
        _cli_daemon(args)
        return
    if args and args[0]=="import-creds":
        _cli_import_creds(args[1] if len(args)>1 else None)
        return
    if args and args[0]=="doctor":
        _cli_doctor()
        return
    if args and args[0]=="setup":
        _cli_setup()
        return
    if args and args[0] in ("upgrade","update"):
        _cli_upgrade()
        return
    if args and args[0]=="--agent":
        # nx --agent <key> "<task…>" [--approve] [--success "<criterion>"] [--json]
        _arest = list(args[1:])
        _ajson = "--json" in _arest
        _aapprove = ("--approve" in _arest) or ("--yes" in _arest)   # pre-authorize DESTRUCTIVE ops (operational)
        _arest = [a for a in _arest if a not in ("--json", "--approve", "--yes")]
        _asuccess = ""
        if "--success" in _arest:
            _si = _arest.index("--success")
            _asuccess = " ".join(_arest[_si + 1:])   # everything after --success is the operator's success criterion
            _arest = _arest[:_si]
        _akey = _arest[0] if _arest else ""
        _atask = " ".join(_arest[1:])
        _cli_agent(_akey, _atask, as_json=_ajson, success=_asuccess, _approve=_aapprove)
        return
    if args and args[0]=="--loop":
        # nx --loop [--dry-run] [--llm] [--all] [--world <w>]...  — born-safe autonomy loop (fires T1 reads only)
        import nx_loop as _nl
        from nx_prompts import NX_WORLD_CONTEXT as _NWC
        _lp = _nl.parse_loop_args(args[1:])
        _lworlds = _nl.resolve_worlds(_lp, [w for w in _NWC if w != "lead"])
        _cli_loop_run(_lworlds, dry_run=_lp["dry_run"], use_llm=_lp["use_llm"], rounds=_lp.get("rounds", 1))
        return
    if args and args[0]=="message":
        # nx message [telegram|imessage <h>|email|whatsapp|on <ch>|off <ch>] — report-back channels
        import nx_message as _msg, getpass as _gp
        _psec = lambda label: _gp.getpass("  " + label + " ❯ ").strip()
        _pin = lambda label: input("  " + label + " ❯ ").strip()
        print(_msg.handle_message_command(args[1:], prompt_secret=_psec, prompt=_pin))
        return
    if args and args[0]=="host-agent":
        # nx host-agent [--once] [--poll <s>] — the local executor for actions you approve from ANOTHER
        # surface (Telegram/web). It claims each approved action and runs it HERE via the same proven
        # connectors /publish uses, then reports the result back. Long-running; Ctrl-C to stop.
        import nx_message as _msg
        _ha = list(args[1:])
        _once = "--once" in _ha
        _poll = 5
        if "--poll" in _ha:
            try: _poll = max(1, int(_ha[_ha.index("--poll") + 1]))
            except Exception: _poll = 5
        _cfg = load_config()
        if not _cfg or not (_cfg.get("token") or _cfg.get("api_key")):
            print(gold("  Sign-in required. Run `nx login`."));return
        def _ha_ev(ev, data):
            if ev == "claimed":
                print(gold("  ⟳ running %s · %s …" % (data.get("server"), data.get("tool"))))
            elif ev == "ran":
                mark = "✅" if data.get("ok") else "❌"
                print(gold("  %s %s · %s — %s" % (mark, data.get("server"), data.get("tool"), (data.get("summary") or "")[:140])))
        print(gold("  ✦ NX host-agent — I'll run the actions you approve, right here on this machine. Ctrl-C to stop."))
        try:
            _out = _msg.run_host_agent(poll_s=_poll, once=_once, on_event=_ha_ev)
            print(gold("  ✦ host-agent stopped (%s)." % (_out.get("stopped") or ("ran %d" % _out.get("ran", 0)))))
        except KeyboardInterrupt:
            print(gold("\n  ✦ host-agent stopped."))
        return
    if args and args[0]=="sync-connections":
        # nx sync-connections — push a metadata-only snapshot of what's connected locally so Telegram + web show
        # the SAME connected set (1 account, 1 brain). No credentials ever leave the machine.
        import nx_message as _msg
        _cfg = load_config()
        if not _cfg or not (_cfg.get("token") or _cfg.get("api_key")):
            print(gold("  Sign-in required. Run `nx login`."));return
        _snap = _msg.collect_local_connections()
        _res = _msg.push_connections_snapshot()
        if _res.get("ok"):
            print(gold("  ✦ synced %d connections to your account — now visible on Telegram + web." % _res.get("synced", len(_snap))))
        else:
            print(gold("  ✦ sync failed: %s" % _res.get("error", "unknown")))
        return
    if args and args[0]=="sync-creations":
        # nx sync-creations — push a metadata-only snapshot of what you've GENERATED locally (skills/integrations/
        # tools + honest proven/pending) so web + Telegram show the SAME `nx created` set. No code, no credentials.
        import nx_message as _msg
        _cfg = load_config()
        if not _cfg or not (_cfg.get("token") or _cfg.get("api_key")):
            print(gold("  Sign-in required. Run `nx login`."));return
        _snap = _msg.collect_local_creations()
        _res = _msg.push_creations_snapshot()
        if _res.get("ok"):
            print(gold("  ✦ synced %d creations to your account — now visible on Telegram + web." % _res.get("synced", len(_snap))))
        else:
            print(gold("  ✦ sync failed: %s" % _res.get("error", "unknown")))
        return
    if args and args[0]=="sync-supply":
        # nx sync-supply — push the /supply bindings (which agent can send as what) on demand and REPORT the
        # result. The automatic sync is best-effort and swallows its errors by design, because a sync failure
        # must never make a working /supply look broken. That silence is right for the background and wrong
        # when an operator is asking "why isn't my crew on the web?" — so this is the loud version.
        import nx_message as _msg
        _cfg = load_config()
        if not _cfg or not (_cfg.get("token") or _cfg.get("api_key")):
            print(gold("  Sign-in required. Run `nx login`."));return
        _snap = _msg.collect_local_agent_channels()
        if not _snap:
            print(gold("  ✦ no supplied channels on this machine — nothing to sync. Run /supply first."));return
        _res = _msg.push_agent_channels_snapshot()
        if _res.get("ok"):
            _proven = sum(1 for _c in _snap if _c.get("verifiedAt"))
            print(gold("  ✦ synced %d bindings to your account — %d proven, %d not yet tested."
                       % (_res.get("synced", len(_snap)), _proven, len(_snap) - _proven)))
            if _res.get("skipped"):
                print(dim("    skipped: %s" % ", ".join(map(str, _res.get("skipped") or []))[:200]))
        else:
            print(gold("  ✦ sync failed: %s" % _res.get("error", "unknown")))
        return
    if args and args[0]=="connect":
        # nx connect <provider> <api-key|token> — provision an integration with YOUR OWN credential. The PROOF
        # GATE verifies it with a REAL call before it's marked connected: a rejected key comes back honestly as
        # "not connected", never faked. (You provide the credential; it goes straight to your vault.)
        import nx_message as _msg, requests as _rq
        _rest = list(args[1:])
        if len(_rest) < 2:
            print(gold("  usage: nx connect <provider> <api-key-or-token>"));return
        _prov = _rest[0].strip().lower(); _key = _rest[1]
        _cfg = load_config()
        if not _cfg or not (_cfg.get("token") or _cfg.get("api_key")):
            print(gold("  Sign-in required. Run `nx login`."));return
        _tok = _msg._refresh_device_token()
        try:
            r = _rq.post(_msg._auth_base().rstrip("/") + "/api/integrations/connect",
                         json={"providerSlug": _prov, "apiKeyValue": _key},
                         headers={"Authorization": "Bearer " + _tok, "Content-Type": "application/json"}, timeout=30)
            _d = r.json() if r.content else {}
        except Exception as _e:
            print(gold("  connect failed: %s" % type(_e).__name__));return
        _kind = _d.get("kind"); _ver = _d.get("verified")
        if _kind == "connected":
            print(gold("  ✦ %s connected%s." % (_prov, " (verified live ✓)" if _ver else " (stored)")))
        elif _kind == "needs_reauth":
            _err = (_d.get("connection") or {}).get("errorMessage") or "the provider rejected the credential"
            print(gold("  ✗ %s NOT connected — %s. Fix the key and retry." % (_prov, _err)))
        else:
            print(gold("  %s: %s" % (_prov, _d.get("error") or _kind or "unknown")))
        return
    if args and args[0]=="skills":
        # nx skills [prove <cmd>] — your created skills with HONEST status (proven/pending). A created skill is
        # PENDING until the GATE proves it (proves on first use, or run `nx skills prove <cmd>`).
        import nx_creator as _cr
        _rest = list(args[1:])
        if _rest and _rest[0] == "prove" and len(_rest) > 1:
            _cmd = _rest[1]
            print(gold("  proving %s — running it through the gate…" % _cmd))
            _v = _cr.prove_and_mark_skill(_cmd)
            if _v.ready:
                print(gold("  🟢 %s — proven (it runs)." % _cmd))
            else:
                print(gold("  🟡 %s — still pending: %s" % (_cmd, (_v.fail or {}).get("detail", "no output"))))
            return
        _skills = _cr.list_user_skills()
        if not _skills:
            print(gold("  No skills yet. Create one with /create in a session."));return
        print(gold("\n  ✦ Your skills"))
        for _s in _skills:
            _mark = "🟢 proven" if _s.get("status") == "proven" else "🟡 pending"
            print(gold("  %-16s %s  %s" % (_s.get("cmd"), _mark, (_s.get("desc") or "")[:48])))
        print(gold("  Prove a pending one:  nx skills prove <cmd>\n"))
        return
    if args and args[0]=="agents":
        # nx agents [prove <name|id>] — your CREATED agents with HONEST status (proven/pending). A created agent is
        # PENDING until the GATE runs it for real (RUN-IS-REAL). `prove` runs one real turn and records the verdict.
        import nx_creator as _cr, nx_message as _msg
        _cfg = load_config()
        if not _cfg or not (_cfg.get("token") or _cfg.get("api_key")):
            print(gold("  Sign-in required. Run `nx login`."));return
        _tok = _msg._refresh_device_token()
        _base = _msg._auth_base().rstrip("/")
        _rest = list(args[1:])
        if _rest and _rest[0] == "prove" and len(_rest) > 1:
            _q = " ".join(_rest[1:]).strip()
            _aid, _nm = _q, _q  # accept a raw agentId, or resolve a name via the roster
            try:
                import nx_agents as _A
                _, _customs = _A._fetch_roster(_base, _tok)
                for _c in (_customs or []):
                    if str(_c.get("agentId")) == _q or str(_c.get("name") or "").lower() == _q.lower():
                        _aid = str(_c.get("agentId")); _nm = _c.get("name") or _q; break
            except Exception:
                pass
            print(gold("  proving %s — running one real turn (RUN-IS-REAL)…" % _nm))
            _v = _cr.prove_and_mark_agent(_aid, name=_nm)
            if _v.ready:
                print(gold("  🟢 %s — proven (it ran for real)." % _nm))
            else:
                print(gold("  🟡 %s — still pending: %s" % (_nm, (_v.fail or {}).get("detail", "no run"))))
            return
        _agents = _cr.list_user_agents(_base, _tok)
        if not _agents:
            print(gold("  No custom agents yet. Create one with /crew → ＋ Create your own."));return
        print(gold("\n  ✦ Your agents"))
        for _a in _agents:
            _mark = "🟢 proven" if _a.get("status") == "proven" else "🟡 pending"
            print(gold("  %-18s %s  %s" % ((_a.get("name") or "agent")[:18], _mark, (_a.get("agentId") or "")[:12])))
        print(gold("  Prove a pending one:  nx agents prove <name>\n"))
        return
    if args and args[0]=="tools":
        # nx tools [prove <name>] — your GENERATED tools with HONEST status. compute tools run SANDBOXED (real
        # output -> proven; an escape attempt is HELD); action tools route through the WALL (an untouchable is HELD).
        import nx_creator as _cr
        _rest = list(args[1:])
        if _rest and _rest[0] == "prove" and len(_rest) > 1:
            _nm = _rest[1]
            print(gold("  proving %s — executing it through the gate…" % _nm))
            _v = _cr.prove_and_mark_tool(_nm)
            if _v.ready:
                print(gold("  🟢 %s — proven (%s)." % (_nm, (_v.evidence or {}).get('sample', 'ran'))))
