    _check_for_update_async()
    _load_bundled_skills_into_prompts()
    _load_user_skills_into_prompts()

    try:
        if use_ui:
            run_chat(cfg)
        else:
            run_nx_repl(cfg)
    finally:
        sys.stdout.write(SHOW_CURSOR);sys.stdout.flush()

